"adm.ms_title": ["Messages", "संदेश"],
"adm.ms_sub": ["Send a message to representatives' offices and answer their replies. Each office's replies are a private conversation with GrievIQ. Case work stays on the case itself.", "जनप्रतिनिधियों के कार्यालयों को संदेश भेजें और उनके उत्तरों का जवाब दें। हर कार्यालय के उत्तर GrievIQ के साथ एक निजी बातचीत हैं। मामलों से जुड़ा काम मामले पर ही होता है।"],
"adm.ms_readonly": ["You can read messages and replies. Only the super admin and operations admins send messages.", "आप संदेश और उत्तर पढ़ सकते हैं। संदेश केवल सुपर एडमिन और संचालन एडमिन भेजते हैं।"],
"adm.ms_new": ["New message", "नया संदेश"],
"adm.ms_new_sub": ["It appears under the bell in the representative console and as a phone alert where turned on. Anyone who hasn't seen it after 6 hours gets a short reminder email (no details) with steps to turn on phone alerts.", "यह जनप्रतिनिधि कंसोल में घंटी के नीचे और जहाँ चालू हो वहाँ फ़ोन पर सूचना के रूप में दिखेगा। जिसने 6 घंटे बाद भी इसे नहीं देखा, उसे एक छोटा अनुस्मारक ईमेल (बिना विवरण) फ़ोन सूचनाएँ चालू करने के चरणों के साथ मिलेगा।"],
