"adm.ms_dl_title": ["Delivery of notices", "सूचनाओं की डिलीवरी"],
"adm.ms_dl_sub": ["Offices get notices under the bell and as phone alerts. A notice still unseen after 6 hours, with no phone alert delivered, brings one short reminder email per person (no details, with steps to turn on phone alerts).", "कार्यालयों को घंटी के नीचे और फ़ोन पर सूचनाएँ मिलती हैं। जो सूचना 6 घंटे बाद भी न देखी गई हो और फ़ोन पर न पहुँची हो, उसके लिए हर व्यक्ति को एक छोटा अनुस्मारक ईमेल जाता है (बिना विवरण, फ़ोन सूचनाएँ चालू करने के चरणों के साथ)।"],
"adm.ms_dl_off": ["Phone alerts aren't set up yet: add the two notification keys (VAPID) to the website and the scheduler, as in the setup steps. Until then, unseen notices bring reminder emails after 6 hours.", "फ़ोन सूचनाएँ अभी सेट नहीं हैं: सेटअप चरणों के अनुसार वेबसाइट और शेड्यूलर में दोनों सूचना कुंजियाँ (VAPID) जोड़ें। तब तक न देखी गई सूचनाओं पर 6 घंटे बाद अनुस्मारक ईमेल जाएँगे।"],
"adm.ms_dl_today": ["Emails sent today (free plan: 100 a day)", "आज भेजे गए ईमेल (मुफ़्त योजना: 100 प्रतिदिन)"],
