"adm.ms_dl_warn": ["Today's emails are close to the free limit of 100. Ask offices to turn on phone alerts, or move to Resend's paid plan.", "आज के ईमेल 100 की मुफ़्त सीमा के क़रीब हैं। कार्यालयों से फ़ोन सूचनाएँ चालू करने को कहें, या Resend की सशुल्क योजना लें।"],
