"adm.fb_sub": ["What citizens tell us about the GrievIQ app through the \"Send feedback\" form. Each item is kept for one year, then deleted automatically.", "नागरिक \"फ़ीडबैक भेजें\" फ़ॉर्म से GrievIQ ऐप के बारे में जो बताते हैं। हर फ़ीडबैक एक साल तक रखा जाता है, फिर अपने-आप मिटा दिया जाता है।"],
