"fb.too_many": ["You have sent a lot of feedback today. Please try again tomorrow.", "आपने आज बहुत फ़ीडबैक भेजा है। कृपया कल फिर कोशिश करें।"],
"fb.email_err": ["Please check your email address, or leave it empty.", "कृपया अपना ईमेल पता जाँचें, या उसे ख़ाली छोड़ दें।"],
"priv.ratings": ["If you rate how your complaint was handled, your rating and any comment are seen by your representative's office (the representative and office managers) and GrievIQ staff. Ratings are never shown publicly. Your comment is removed together with your other details when your case is anonymised.", "यदि आप अपनी शिकायत की कार्यवाही को रेट करते हैं, तो आपकी रेटिंग और कोई भी टिप्पणी आपके जनप्रतिनिधि का कार्यालय (जनप्रतिनिधि और कार्यालय प्रबंधक) और GrievIQ स्टाफ़ देखते हैं। रेटिंग कभी सार्वजनिक नहीं की जाती। जब आपके मामले को गुमनाम किया जाता है, तब आपकी टिप्पणी आपके अन्य विवरणों के साथ हटा दी जाती है।"],
"priv.feedback": ["If you send feedback about the app, we keep what you wrote (and your email, if you gave it) for one year so our team can read it and reply, then delete it. Your feedback is never sent to representatives.", "यदि आप ऐप के बारे में फ़ीडबैक भेजते हैं, तो हम आपका लिखा हुआ (और आपका ईमेल, यदि दिया हो) एक साल तक रखते हैं ताकि हमारी टीम उसे पढ़कर जवाब दे सके, फिर मिटा देते हैं। आपका फ़ीडबैक प्रतिनिधियों को कभी नहीं भेजा जाता।"],
"adm.nav_areas": ["Areas", "क्षेत्र"],
"adm.ar_page_title": ["GrievIQ Admin — Areas", "GrievIQ एडमिन — क्षेत्र"],
"adm.ar_title": ["Areas", "क्षेत्र"],
"adm.ar_sub": ["The cities and districts GrievIQ covers. Add one, then its wards and villages, typed in one at a time or from a spreadsheet. Switch it on when it is ready: until then citizens don't see it.", "वे शहर और ज़िले जिन्हें GrievIQ कवर करता है। एक जोड़ें, फिर उसके वार्ड और गाँव — एक-एक करके टाइप करके या स्प्रेडशीट से। तैयार होने पर उसे चालू करें: तब तक नागरिकों को वह नहीं दिखता।"],
"adm.ar_list_h": ["All areas", "सभी क्षेत्र"],
