"adm.ar_add_h": ["Add a city or district", "शहर या ज़िला जोड़ें"],
"adm.ar_add_p": ["It starts as \"Being set up\": citizens won't see it until you switch it on.", "यह \"तैयारी में\" से शुरू होता है: जब तक आप इसे चालू नहीं करते, नागरिकों को यह नहीं दिखेगा।"],
"adm.ar_f_name": ["Name", "नाम"],
"adm.ar_f_name_h": ["In English, as it should appear, e.g. Kanpur. It also becomes the web address: grieviq.in/kanpur", "अंग्रेज़ी में, जैसे दिखना चाहिए, जैसे Kanpur। यही वेब पता भी बनेगा: grieviq.in/kanpur"],
