"adm.ar_created": ["Area added. Next, add its wards and villages.", "क्षेत्र जोड़ दिया गया। अब इसके वार्ड और गाँव जोड़ें।"],
"adm.ar_back": ["← All areas", "← सभी क्षेत्र"],
"adm.ar_not_found": ["That area wasn't found.", "वह क्षेत्र नहीं मिला।"],
"adm.ar_not_set_up": ["Areas aren't set up yet. Run the database update part14-areas.sql, then refresh this page.", "क्षेत्र अभी सेट नहीं हैं। डेटाबेस अपडेट part14-areas.sql चलाएँ, फिर यह पेज रीफ़्रेश करें।"],
"adm.ar_ready_h": ["Ready for citizens?", "नागरिकों के लिए तैयार?"],
"adm.ar_chk_units": ["Wards and villages added: {w} wards, {v} villages", "जोड़े गए वार्ड और गाँव: {w} वार्ड, {v} गाँव"],
"adm.ar_chk_email": ["{x} of {y} have the representative's email. Those without it can't take complaints yet.", "{y} में से {x} में प्रतिनिधि का ईमेल है। जिनमें नहीं है, वे अभी शिकायत नहीं ले सकते।"],
"adm.ar_chk_maps": ["{x} of {y} wards have a map (optional: lets \"Use my location\" find the ward).", "{y} में से {x} वार्डों का मानचित्र है (वैकल्पिक: इससे \"मेरी लोकेशन\" वार्ड ढूँढ पाती है)।"],
"adm.ar_go_live": ["Switch on for citizens", "नागरिकों के लिए चालू करें"],
"adm.ar_go_live_need": ["Add at least one ward or village with the representative's email first.", "पहले प्रतिनिधि के ईमेल सहित कम से कम एक वार्ड या गाँव जोड़ें।"],
"adm.ar_live_confirm": ["Switch {name} on? Citizens will be able to find it and file complaints there straight away.", "{name} चालू करें? नागरिक तुरंत इसे ढूँढ़ कर वहाँ शिकायत दर्ज कर सकेंगे।"],
"adm.ar_now_live": ["{name} is now live for citizens.", "{name} अब नागरिकों के लिए चालू है।"],
"adm.ar_go_off": ["Switch off", "बंद करें"],
"adm.ar_off_why": ["Why are you switching it off? (Complaints already filed are not affected.)", "आप इसे क्यों बंद कर रहे हैं? (पहले से दर्ज शिकायतों पर असर नहीं पड़ेगा।)"],
"adm.ar_off_btn": ["Switch off for citizens", "नागरिकों के लिए बंद करें"],
"adm.ar_now_off": ["{name} is switched off. Citizens can no longer find it or file new complaints there.", "{name} बंद कर दिया गया। नागरिक अब इसे ढूँढ़ या वहाँ नई शिकायत दर्ज नहीं कर सकते।"],
"adm.ar_cancel": ["Cancel", "रद्द करें"],
"adm.ar_e_reason": ["Please give a reason (at least 10 characters).", "कृपया कारण बताएँ (कम से कम 10 अक्षर)।"],
