"adm.ar_way_type_p": ["A short form. Good for a few at a time, or to fix one that is missing.", "एक छोटा फ़ॉर्म। कुछ एक बार में जोड़ने, या छूटे हुए को जोड़ने के लिए।"],
"adm.ar_way_csv": ["Upload a spreadsheet", "स्प्रेडशीट अपलोड करें"],
"adm.ar_way_csv_p": ["Many at once from a CSV file. You see what will happen before anything is saved.", "CSV फ़ाइल से एक साथ कई। कुछ भी सहेजने से पहले आप देख सकते हैं कि क्या होगा।"],
"adm.ar_way_map": ["Upload the ward map", "वार्ड मानचित्र अपलोड करें"],
"adm.ar_way_map_p": ["Optional. Lets \"Use my location\" and address search find the right ward.", "वैकल्पिक। इससे \"मेरी लोकेशन\" और पता खोज सही वार्ड ढूँढ पाते हैं।"],
