"adm.ar_h_localities": ["Mohallas, colonies or hamlets citizens may search for, separated by ; (semicolon).", "मोहल्ले, कॉलोनियाँ या पुरवे जिन्हें नागरिक खोज सकते हैं, ; (सेमीकोलन) से अलग करें।"],
