"rep.fwd_office_none": ["No office on file: choose \"Office not in the list\"", "कोई कार्यालय दर्ज नहीं: \"कार्यालय सूची में नहीं\" चुनें"],
"rep.fwd_office_other": ["Office not in the list", "कार्यालय सूची में नहीं"],
"rep.fwd_office_name": ["Office name", "कार्यालय का नाम"],
"rep.fwd_how": ["How did you contact them?", "आपने उनसे कैसे संपर्क किया?"],
"rep.fwd_err_how": ["Choose how you contacted the office.", "चुनें कि आपने कार्यालय से कैसे संपर्क किया।"],
"rep.fwd_err_oname": ["Write the office's name (at least 3 characters).", "कार्यालय का नाम लिखें (कम से कम 3 अक्षर)।"],
"rep.fwd_err_office": ["That office isn't available for this ward and department. Choose again.", "वह कार्यालय इस वार्ड और विभाग के लिए उपलब्ध नहीं है। फिर से चुनें।"],
