"adm.ss_sub": ["What GrievIQ publishes for offices: plans and prices, GST, discounts, the company's details and contacts, payment policy and claims.", "GrievIQ कार्यालयों के लिए जो प्रकाशित करता है: योजनाएँ और शुल्क, GST, छूट, कंपनी का विवरण और संपर्क, भुगतान नीति और दावे।"],
"adm.ss_note": ["Changes are saved as a <b>draft</b> first; nothing public changes until the super admin presses <b>Publish</b>. Every published version is kept and can be brought back. Discounts belong to a plan, never to one office or party, so every party pays the same.", "बदलाव पहले <b>ड्राफ़्ट</b> के रूप में सहेजे जाते हैं; सुपर एडमिन के <b>प्रकाशित करें</b> दबाने तक सार्वजनिक रूप से कुछ नहीं बदलता। हर प्रकाशित संस्करण रखा जाता है और वापस लाया जा सकता है। छूट किसी योजना पर होती है, कभी किसी एक कार्यालय या दल के लिए नहीं, ताकि हर दल समान शुल्क दे।"],
