"adm.ss_not_ready": ["This page needs the database step part27 before anything can be saved. Until then, the starting prices and details are shown everywhere.", "कुछ भी सहेजने से पहले इस पृष्ठ के लिए डेटाबेस चरण part27 आवश्यक है। तब तक हर जगह आरंभिक शुल्क और विवरण दिखाए जाते हैं।"],
