"adm.ss_refund_help": ["Shown under the prices once filled in (both languages). Payment providers such as Razorpay ask for this before approving a business. Have it checked by your lawyer or accountant.", "भरने के बाद शुल्क के नीचे दिखाई जाती है (दोनों भाषाओं में)। Razorpay जैसे भुगतान प्रदाता किसी व्यवसाय को स्वीकृति देने से पहले यह माँगते हैं। अपने वकील या लेखाकार से जँचवा लें।"],
