"adm.ss_retire_q": ["Retire this plan? It disappears from the public page but is kept for the record. You can bring it back.", "यह योजना सेवानिवृत्त करें? यह सार्वजनिक पृष्ठ से हट जाएगी पर रिकॉर्ड में रहेगी। आप इसे वापस ला सकते हैं।"],
