"adm.pr_sub": ["Offices that asked for a free pilot on the For offices page. Call them back within the time promised on the page.", "जिन कार्यालयों ने कार्यालयों वाले पृष्ठ पर निःशुल्क पायलट माँगा है। पृष्ठ पर बताए समय में उन्हें वापस फ़ोन करें।"],
"adm.pr_note": ["Each person agreed that GrievIQ may use these details <b>only</b> to contact them about a pilot. Don't share them or add them to any other list. Requests are deleted automatically one year after they were sent.", "हर व्यक्ति ने केवल पायलट के संबंध में संपर्क के लिए <b>ही</b> इन विवरणों के उपयोग की सहमति दी है। इन्हें साझा न करें, न किसी अन्य सूची में जोड़ें। अनुरोध भेजे जाने के एक वर्ष बाद स्वतः हट जाते हैं।"],
