"lp.page_title": ["GrievIQ for offices — Constituency Service & Grievance Redressal Platform", "कार्यालयों के लिए GrievIQ — क्षेत्र सेवा एवं शिकायत निवारण मंच"],
"lp.for_offices": ["For offices", "कार्यालयों के लिए"],
