"perf.d_assignment": ["A case forwarded to an office counts against that office until it is forwarded again. A \"not ours\" case starts fresh at the next office.", "किसी कार्यालय को भेजा गया मामला तब तक उस कार्यालय के खाते में गिना जाता है जब तक उसे फिर से न भेजा जाए। \"हमारा नहीं\" वाला मामला अगले कार्यालय पर नए सिरे से शुरू होता है।"],
