"perf.d_with_now": ["Cases waiting for the department's work, as of now.", "वे मामले जो अभी विभाग के काम की प्रतीक्षा में हैं।"],
"perf.d_overdue_now_t": ["Overdue now", "अभी समय से पीछे"],
"perf.d_overdue_now": ["Of those, cases past the target time (the type's days, or a later date the department gave).", "उनमें से वे मामले जो समय-सीमा (प्रकार के दिन, या विभाग की बताई बाद की तारीख़) से पीछे हैं।"],
"perf.d_first_reply_t": ["First reply", "पहला उत्तर"],
"perf.d_first_reply": ["Median days from forwarding to the first reply: scheduled, started, done, not ours or can't do.", "भेजने से पहले उत्तर (तय, शुरू, पूरा, हमारा नहीं या नहीं हो सकता) तक के दिनों का मध्य मान।"],
"perf.d_on_time_t": ["Work done on time", "समय पर काम पूरा"],
"perf.d_on_time": ["Of cases where the work was reported done or the target has passed, the share reported done by the target.", "जिन मामलों में काम पूरा बताया गया या समय-सीमा बीत गई, उनमें से समय-सीमा तक पूरा बताए गए मामलों का हिस्सा।"],
"perf.d_to_fixed_t": ["Time to fixed", "ठीक होने में समय"],
"perf.d_to_fixed": ["Median days from forwarding to a passed field check by the representative's team.", "भेजने से जनप्रतिनिधि की टीम की सफल मौके की जाँच तक के दिनों का मध्य मान।"],
"perf.d_fixed_first_t": ["Fixed first time", "पहली बार में ठीक"],
"perf.d_fixed_first": ["Of first field checks after the department said the work was done, the share that found it fixed.", "विभाग के काम पूरा बताने के बाद की पहली मौके की जाँचों में से, जिनमें काम ठीक पाया गया उनका हिस्सा।"],
"perf.d_reopened_t": ["Reopened by citizens", "नागरिकों ने फिर खोला"],
"perf.d_reopened": ["Of cases that closed, the share a citizen reopened.", "बंद हुए मामलों में से जिन्हें नागरिक ने फिर खोला उनका हिस्सा।"],
"perf.d_rating_t": ["Citizen rating", "नागरिक रेटिंग"],
"perf.d_rating": ["How satisfied citizens said they were with the department's work, on the five-answer scale. An average only from 5 ratings.", "नागरिकों ने विभाग के काम से कितनी संतुष्टि बताई, पाँच उत्तरों वाले पैमाने पर। औसत केवल 5 रेटिंग होने पर।"],
"perf.d_own_replies_t": ["Replies by the department itself", "विभाग के अपने उत्तर"],
"perf.d_own_replies": ["Replies the department made on its own dashboard, out of all its replies (the rest were recorded by the representative's office).", "विभाग के सभी उत्तरों में से जो उसने अपने डैशबोर्ड पर स्वयं दिए (बाकी जनप्रतिनिधि के कार्यालय ने दर्ज किए)।"],
"perf.d_not_ours_t": ["\"Not ours\" and \"Can't do\"", "\"हमारा नहीं\" और \"नहीं हो सकता\""],
"perf.d_not_ours": ["Counts, for information. \"Not ours\" mostly reflects how cases were routed, so it is not counted against the office.", "संख्याएँ, जानकारी के लिए। \"हमारा नहीं\" ज़्यादातर मामलों को भेजने के तरीके को दिखाता है, इसलिए कार्यालय के विरुद्ध नहीं गिना जाता।"],
"perf.d_cant_do_t": ["Reasons for \"Can't do\"", "\"नहीं हो सकता\" के कारण"],
"perf.d_cant_do": ["The department's reasons are on each case.", "विभाग के कारण हर मामले पर हैं।"],
"perf.d_active_officers_t": ["Officers signed in", "साइन इन करने वाले अधिकारी"],
"perf.d_active_officers": ["The office's officers who signed in to the department dashboard in the last 30 days.", "कार्यालय के वे अधिकारी जिन्होंने पिछले 30 दिनों में विभाग डैशबोर्ड पर साइन इन किया।"],
"perf.d_min_t": ["Small numbers", "कम संख्याएँ"],
"perf.d_min": ["A share or median is shown only from 5 cases; below that you see how many cases there are. Medians are used so one stuck case does not distort the picture.", "हिस्सा या मध्य मान केवल 5 मामलों से दिखाया जाता है; उससे कम पर मामलों की संख्या दिखती है। मध्य मान इसलिए ताकि एक अटका मामला तस्वीर न बिगाड़े।"],
"adm.nav_dept_perf": ["Department performance", "विभागों का प्रदर्शन"],
