"adm.pf_title": ["Department performance", "विभागों का प्रदर्शन"],
"adm.pf_sub": ["How quickly department offices reply and get the work done, whether the work passes the field check, and what citizens think. Worked out live from the department steps on each case.", "विभागीय कार्यालय कितनी जल्दी उत्तर देते हैं और काम पूरा करते हैं, काम मौके की जाँच में सही निकलता है या नहीं, और नागरिक क्या सोचते हैं। हर मामले के विभागीय चरणों से अभी गणना।"],
"adm.pf_note": ["During the pilot there is no single score or ranking: with small numbers a rank misleads. A share or median is shown only from 5 cases; below that you see the count. Each forwarding counts against the office it went to.", "पायलट के दौरान कोई एकल अंक या रैंकिंग नहीं: कम संख्याओं में रैंक भ्रामक होती है। हिस्सा या मध्य मान केवल 5 मामलों से दिखाया जाता है; उससे कम पर संख्या दिखती है। हर बार भेजना उसी कार्यालय के खाते में गिना जाता है जिसे भेजा गया।"],
