"rep.ov_how_rating": ["Citizen ratings: after a case closes, the citizen can rate your office on a five-answer scale (and the department, if one worked on it). Shown for cases your office resolved, by the date rated. An average is shown only from 5 ratings, so a single answer can't stand for your office.", "नागरिकों की रेटिंग: मामला बंद होने के बाद नागरिक आपके कार्यालय को पाँच उत्तरों वाले पैमाने पर रेट कर सकते हैं (और विभाग को, यदि किसी विभाग ने काम किया)। आपके कार्यालय द्वारा निस्तारित मामलों के लिए, रेटिंग की तारीख के अनुसार। औसत केवल 5 रेटिंग होने पर दिखाया जाता है, ताकि एक अकेला उत्तर आपके कार्यालय की पहचान न बने।"],
