"adm.dp_sub": ["The government offices that handle each kind of problem in each area, with their official public contacts. Representatives will see the right office on each complaint.", "हर क्षेत्र में हर प्रकार की समस्या देखने वाले सरकारी कार्यालय, उनके आधिकारिक सार्वजनिक संपर्कों के साथ। जनप्रतिनिधियों को हर शिकायत पर सही कार्यालय दिखेगा।"],
"adm.dp_not_set_up": ["The department directory isn't set up yet. Run the database update part21-departments.sql.", "विभाग निर्देशिका अभी तैयार नहीं है। डेटाबेस अपडेट part21-departments.sql चलाएँ।"],
"adm.dp_area_not_found": ["That area was not found.", "वह क्षेत्र नहीं मिला।"],
"adm.dp_note_official": ["Only official public contacts: helplines, office phones and emails, official WhatsApp numbers and complaint websites, each with where it came from (an official web page or an RTI reply). Never an officer's personal mobile, unless they have agreed and that agreement is recorded.", "केवल आधिकारिक सार्वजनिक संपर्क: हेल्पलाइन, कार्यालय के फ़ोन और ईमेल, आधिकारिक व्हाट्सऐप नंबर और शिकायत वेबसाइट, हर एक के साथ यह कि वह कहाँ से लिया गया (आधिकारिक वेब पेज या आरटीआई उत्तर)। किसी अधिकारी का निजी मोबाइल कभी नहीं, जब तक उन्होंने सहमति न दी हो और वह सहमति दर्ज न हो।"],
"adm.dp_note_match": ["An office that covers only certain wards is shown before one that covers the whole area. Offices are retired, never deleted, so old records keep their meaning. Every change is recorded in the audit log.", "केवल कुछ वार्डों को देखने वाला कार्यालय पूरे क्षेत्र को देखने वाले कार्यालय से पहले दिखाया जाता है। कार्यालय हटाए नहीं जाते, सेवानिवृत्त किए जाते हैं, ताकि पुराने रिकॉर्ड का अर्थ बना रहे। हर बदलाव ऑडिट लॉग में दर्ज होता है।"],
"adm.dp_note_request": ["Your changes are sent as requests. A super admin or operations admin approves them on the Change requests page before they appear here.", "आपके बदलाव अनुरोध के रूप में भेजे जाते हैं। सुपर एडमिन या ऑपरेशंस एडमिन उन्हें बदलाव अनुरोध पृष्ठ पर स्वीकृत करते हैं, तभी वे यहाँ दिखते हैं।"],
"adm.dp_note_readonly": ["You can view this page but not change it.", "आप यह पृष्ठ देख सकते हैं, पर बदल नहीं सकते।"],
