"adm.dp_h_name_en": ["As the office calls itself, for example \"Jal Kal Vibhag, {area}\".", "जैसा कार्यालय स्वयं को कहता है, उदाहरण \"Jal Kal Vibhag, {area}\"।"],
"adm.dp_h_name_hi": ["For example \"जलकल विभाग, {areaHi}\". Shown to people using GrievIQ in Hindi.", "उदाहरण \"जलकल विभाग, {areaHi}\"। हिन्दी में GrievIQ उपयोग करने वालों को दिखता है।"],
"adm.dp_h_departments": ["Tick every type it handles. A Nagar Nigam zone, for example, may handle both sanitation and roads.", "हर वह प्रकार चुनें जो यह देखता है। उदाहरण के लिए नगर निगम का एक ज़ोन सफ़ाई और सड़क दोनों देख सकता है।"],
