"adm.dp_ward_select_shown": ["Select those shown", "दिख रहे सभी चुनें"],
"adm.dp_ward_clear": ["Clear", "हटाएँ"],
"adm.dp_ward_chosen": ["{n} of {total} chosen", "{total} में से {n} चुने गए"],
"adm.dp_ward_no_match": ["No ward or village matches.", "कोई वार्ड या गाँव मेल नहीं खाता।"],
"adm.dp_h_contacts": ["Give at least one way to reach the office. Use only numbers and addresses the office publishes itself.", "कार्यालय तक पहुँचने का कम से कम एक तरीका दें। केवल वही नंबर और पते लिखें जो कार्यालय स्वयं प्रकाशित करता है।"],
"adm.dp_h_helpline": ["A short code such as 1533 or 1912, a toll-free number such as 1800 410 1912, or a phone number.", "1533 या 1912 जैसा छोटा नंबर, 1800 410 1912 जैसा टोल-फ़्री नंबर, या कोई फ़ोन नंबर।"],
"adm.dp_h_phone": ["With the STD code, for example 0522 2234567.", "एसटीडी कोड के साथ, उदाहरण 0522 2234567।"],
"adm.dp_h_whatsapp": ["Only the office's own official WhatsApp (a 10-digit mobile number).", "केवल कार्यालय का अपना आधिकारिक व्हाट्सऐप (10 अंकों का मोबाइल नंबर)।"],
"adm.dp_h_website": ["The full address, starting with https://", "पूरा पता, https:// से शुरू"],
"adm.dp_h_hours": ["For example \"Mon–Sat, 10 am – 5 pm\" or \"24 hours\".", "उदाहरण \"सोम–शनि, सुबह 10 – शाम 5\" या \"24 घंटे\"।"],
"adm.dp_officer_sum": ["An officer's own mobile number (only with their agreement)", "किसी अधिकारी का निजी मोबाइल नंबर (केवल उनकी सहमति से)"],
"adm.dp_officer_p": ["Under the Digital Personal Data Protection Act, 2023, a personal number may be kept only if the officer has agreed. Record when and how they agreed. Leave this empty if they haven't.", "डिजिटल व्यक्तिगत डेटा संरक्षण अधिनियम, 2023 के अनुसार निजी नंबर तभी रखा जा सकता है जब अधिकारी ने सहमति दी हो। सहमति कब और कैसे दी, यह दर्ज करें। सहमति न हो तो इसे खाली छोड़ें।"],
"adm.dp_h_consent_how": ["For example \"Said yes by phone to Ravi Kumar, GrievIQ\" or \"Email of 3 Oct 2026\".", "उदाहरण \"GrievIQ के रवि कुमार को फ़ोन पर हाँ कहा\" या \"3 अक्टूबर 2026 का ईमेल\"।"],
"adm.dp_h_source": ["The official web page address, or for example \"RTI reply from Nagar Nigam, 2 Oct 2026\".", "आधिकारिक वेब पेज का पता, या उदाहरण \"नगर निगम का आरटीआई उत्तर, 2 अक्टूबर 2026\"।"],
"adm.dp_h_checked": ["The day someone last confirmed these contacts are correct. After a year the office is marked \"Check again\".", "वह दिन जब किसी ने आख़िरी बार पुष्टि की कि ये संपर्क सही हैं। एक वर्ष बाद कार्यालय पर \"दोबारा जाँचें\" लग जाता है।"],
"adm.dp_h_reason": ["Tell the approver why, for example \"New helpline announced on the Nagar Nigam website\".", "स्वीकृति देने वाले को कारण बताएँ, उदाहरण \"नगर निगम की वेबसाइट पर नई हेल्पलाइन घोषित\"।"],
