"adm.dp_e_UNKNOWN": ["One or more wards are not in this area.", "एक या अधिक वार्ड इस क्षेत्र में नहीं हैं।"],
"adm.dp_e_NO_CONTACT": ["Give at least one way to reach the office: a helpline, phone, email, WhatsApp number or website.", "कार्यालय तक पहुँचने का कम से कम एक तरीका दें: हेल्पलाइन, फ़ोन, ईमेल, व्हाट्सऐप नंबर या वेबसाइट।"],
"adm.dp_e_NO_MAIL": ["This email's domain can't receive email. Please check the spelling.", "इस ईमेल का डोमेन ईमेल प्राप्त नहीं कर सकता। कृपया वर्तनी जाँचें।"],
