"adm.dp_e_officerConsentDate_REQUIRED": ["A personal number needs the date the officer agreed.", "निजी नंबर के साथ अधिकारी की सहमति की तारीख़ आवश्यक है।"],
"adm.dp_e_officerConsentHow_REQUIRED": ["A personal number needs a note of how the officer agreed.", "निजी नंबर के साथ यह लिखना आवश्यक है कि अधिकारी ने सहमति कैसे दी।"],
