"adm.dp_e_unchanged": ["Nothing has changed. Edit at least one detail, or press Cancel.", "कुछ नहीं बदला। कम से कम एक जानकारी बदलें, या रद्द करें दबाएँ।"],
"adm.dp_api_STALE": ["Someone else changed this office while you were working on it, so nothing was saved. The latest version is shown now.", "आपके काम करते समय किसी और ने यह कार्यालय बदल दिया, इसलिए कुछ नहीं सहेजा गया। अब नवीनतम संस्करण दिख रहा है।"],
