"adm.iw_format_p2": ["Upload a ward map (a GeoJSON file, e.g. from bharatlas.com or the municipal corporation). Each ward's name in the file (a property such as <code>Ward Name</code>, <code>ward_name</code> or <code>name</code>) is matched, ignoring capitals, to a ward already added in the chosen area.", "वार्ड मानचित्र अपलोड करें (GeoJSON फ़ाइल, जैसे bharatlas.com या नगर निगम से)। फ़ाइल में हर वार्ड का नाम (जैसे <code>Ward Name</code>, <code>ward_name</code> या <code>name</code>) चुने गए क्षेत्र में पहले से जोड़े गए वार्ड से मिलाया जाता है।"],
