"adm.ck_ph_full_removed": ["Full-size photo removed under the retention policy on {date}; preview kept.", "पूरे आकार की फ़ोटो {date} को संग्रहण नीति के अनुसार हटाई गई; छोटी झलक रखी गई है।"],
