"adm.ss_pm_h": ["Where offices pay", "कार्यालय कहाँ भुगतान करें"],
"adm.ss_pm_help": ["Shown only to signed-in representatives, office managers and department offices, with their bills; never on the public website. New or changed details go live {h} hours after you publish: every super admin is emailed and any of them can cancel the change. Hiding or removing details takes effect at once.", "केवल साइन-इन किए जनप्रतिनिधियों, कार्यालय प्रबंधकों और विभागीय कार्यालयों को उनके बिलों के साथ दिखता है; सार्वजनिक वेबसाइट पर कभी नहीं। नया या बदला विवरण प्रकाशित करने के {h} घंटे बाद लागू होता है: हर सुपर एडमिन को ईमेल जाता है और उनमें से कोई भी बदलाव रद्द कर सकता है। विवरण छिपाना या हटाना तुरंत लागू होता है।"],
"adm.ss_pm_wait": ["A change is waiting: it goes live on {when} (published by {who}).", "एक बदलाव प्रतीक्षा में है: यह {when} को लागू होगा ({who} द्वारा प्रकाशित)।"],
"adm.ss_pm_wait_p": ["Until then offices see the details below. If you didn't expect this change, cancel it.", "तब तक कार्यालयों को नीचे दिया विवरण दिखेगा। यदि आपको इस बदलाव की अपेक्षा नहीं थी, तो इसे रद्द करें।"],
