"adm.bl_page_title": ["GrievIQ Admin — Bills", "GrievIQ एडमिन — बिल"],
"adm.bl_sub": ["Bills for representative and department offices, and the payments they record. Offices pay online (Razorpay, when it is switched on) or by UPI or bank transfer to the details in Prices & site details.", "जनप्रतिनिधि और विभागीय कार्यालयों के बिल, और उनके द्वारा दर्ज भुगतान। कार्यालय ऑनलाइन (Razorpay, जब चालू हो) या शुल्क और साइट विवरण में दिए विवरण पर UPI या बैंक ट्रांसफ़र से भुगतान करते हैं।"],
"adm.bl_note": ["The amount comes from the <b>published prices</b> on the day the bill is made, so every party pays the same; it can't be typed in. Before you confirm a payment, <b>find it in the bank statement</b> (reference, amount and date).", "राशि बिल बनने के दिन के <b>प्रकाशित शुल्क</b> से आती है, ताकि हर दल समान शुल्क दे; इसे टाइप नहीं किया जा सकता। किसी भुगतान की पुष्टि से पहले <b>उसे बैंक विवरण में खोजें</b> (संदर्भ, राशि और तारीख़)।"],
