"adm.bl_on_live": ["On, with LIVE keys. Offices see \"Pay online\" on bills still to pay; a payment marks the bill paid after GrievIQ checks it with Razorpay.", "चालू, LIVE कुंजियों के साथ। कार्यालयों को भुगतान शेष बिलों पर \"ऑनलाइन भुगतान करें\" दिखता है; GrievIQ के Razorpay से जाँचने के बाद भुगतान से बिल भुगतान हो चुका माना जाता है।"],
"adm.bl_on_test": ["On, with TEST keys. Offices see \"Pay online\" marked Test mode: no money moves and bills stay unpaid. Change to LIVE keys when Razorpay has activated the account.", "चालू, TEST कुंजियों के साथ। कार्यालयों को \"ऑनलाइन भुगतान करें\" पर टेस्ट मोड दिखता है: कोई पैसा नहीं जाता और बिलों का भुगतान शेष रहता है। Razorpay के खाता सक्रिय करने पर LIVE कुंजियाँ लगाएँ।"],
"adm.bl_on_off": ["Off. Offices pay by UPI or bank transfer. To switch it on, add the Razorpay keys as Cloudflare secrets (Help → Bills).", "बंद। कार्यालय UPI या बैंक ट्रांसफ़र से भुगतान करते हैं। चालू करने के लिए Razorpay कुंजियाँ Cloudflare सीक्रेट के रूप में जोड़ें (सहायता → बिल)।"],
"adm.bl_on_nodb": ["Waiting for the database update (part42).", "डेटाबेस अपडेट (part42) की प्रतीक्षा है।"],
"adm.bl_on_hook_ok": ["Razorpay's messages (webhook): set up. Last message {when}.", "Razorpay के संदेश (वेबहुक): सेट हैं। अंतिम संदेश {when}।"],
"adm.bl_on_hook_never": ["Razorpay's messages (webhook): set up; none received yet.", "Razorpay के संदेश (वेबहुक): सेट हैं; अभी कोई संदेश नहीं आया।"],
"adm.bl_on_hook_no": ["Razorpay's messages (webhook): not set up. Payments are still checked right after paying and every hour.", "Razorpay के संदेश (वेबहुक): सेट नहीं हैं। भुगतान फिर भी तुरंत बाद और हर घंटे जाँचे जाते हैं।"],
"adm.bl_on_waiting": ["Online payments started and not finished: {n}. Each is checked with Razorpay every hour for 3 days.", "शुरू किए गए पर पूरे न हुए ऑनलाइन भुगतान: {n}। हर एक को 3 दिन तक हर घंटे Razorpay से जाँचा जाता है।"],
"adm.bl_on_refund_h": ["To refund", "लौटाने हैं"],
"adm.bl_on_refund_p": ["Money taken online for a bill that was already paid or cancelled, or for a different amount. Refund it in the Razorpay dashboard (Transactions → Payments → open the reference → Issue refund), then mark it here.", "ऐसे बिल के लिए ऑनलाइन लिया गया पैसा जिसका भुगतान पहले हो चुका था या जो रद्द था, या अलग राशि। इसे Razorpay डैशबोर्ड में लौटाएँ (Transactions → Payments → संदर्भ खोलें → Issue refund), फिर यहाँ दर्ज करें।"],
