"adm.bl_on_why_AMOUNT": ["The amount was different from the bill total.", "राशि बिल की कुल राशि से अलग थी।"],
"adm.bl_on_why_CLOSED": ["The bill was already paid or cancelled.", "बिल पहले ही भुगतान हो चुका था या रद्द था।"],
