"adm.rv_h": ["Review access for Razorpay", "Razorpay के लिए समीक्षा पहुँच"],
"adm.rv_p": ["Razorpay's reviewers ask for a test login to see where offices pay. Switch on review access for one Google account made only for them. GrievIQ then makes a demo office with one sample bill. The demo office is never shown to citizens or in any government dashboard, and it holds no complaints or citizen details.", "Razorpay के समीक्षक यह देखने के लिए टेस्ट लॉगिन माँगते हैं कि कार्यालय कहाँ भुगतान करते हैं। केवल उनके लिए बनाए गए एक Google खाते के लिए समीक्षा पहुँच चालू करें। तब GrievIQ एक नमूना बिल के साथ एक डेमो कार्यालय बनाता है। डेमो कार्यालय कभी नागरिकों को या किसी सरकारी डैशबोर्ड में नहीं दिखता, और उसमें कोई शिकायत या नागरिक का विवरण नहीं होता।"],
"adm.rv_on": ["On for {email}", "{email} के लिए चालू"],
"adm.rv_off": ["Off. Nobody can sign in to the demo office.", "बंद। डेमो कार्यालय में कोई साइन इन नहीं कर सकता।"],
"adm.rv_office": ["Demo office", "डेमो कार्यालय"],
"adm.rv_bill": ["Sample bill", "नमूना बिल"],
"adm.rv_no_bill": ["None open. Switch on again to make one.", "कोई खुला नहीं। बनाने के लिए फिर चालू करें।"],
"adm.rv_give_h": ["What to put in Razorpay's form", "Razorpay के फ़ॉर्म में क्या भरें"],
"adm.rv_give_site": ["Website", "वेबसाइट"],
"adm.rv_give_user": ["Test account username/email", "टेस्ट खाते का यूज़रनेम/ईमेल"],
"adm.rv_give_pass": ["Test account password", "टेस्ट खाते का पासवर्ड"],
"adm.rv_give_pass_v": ["That Google account's own password. Only you know it; it is never typed into GrievIQ.", "उस Google खाते का अपना पासवर्ड। इसे केवल आप जानते हैं; इसे कभी GrievIQ में नहीं लिखा जाता।"],
"adm.rv_give_how": ["How they sign in", "वे कैसे साइन इन करते हैं"],
"adm.rv_give_how_v": ["Open https://grieviq.in/rep, tap Sign in with Google, then open Billing and tap Pay online on the sample bill.", "https://grieviq.in/rep खोलें, Google से साइन इन करें दबाएँ, फिर बिलिंग खोलें और नमूना बिल पर ऑनलाइन भुगतान करें दबाएँ।"],
"adm.rv_email": ["Google account for the reviewers", "समीक्षकों के लिए Google खाता"],
"adm.rv_email_change": ["Use a different Google account", "कोई दूसरा Google खाता उपयोग करें"],
"adm.rv_email_h": ["Make a new Gmail just for this. It can't be anyone's real office, team, officer, official or staff account.", "इसके लिए एक नया Gmail बनाएँ। यह किसी का असली कार्यालय, टीम, अधिकारी, सरकारी या स्टाफ़ खाता नहीं हो सकता।"],
"adm.rv_btn_on": ["Switch on review access", "समीक्षा पहुँच चालू करें"],
"adm.rv_btn_change": ["Change the account", "खाता बदलें"],
"adm.rv_btn_off": ["Switch off review access", "समीक्षा पहुँच बंद करें"],
"adm.rv_off_q": ["Switch off review access? The reviewers' account can't sign in any more and the sample bill is cancelled.", "समीक्षा पहुँच बंद करें? समीक्षकों का खाता अब साइन इन नहीं कर सकेगा और नमूना बिल रद्द हो जाएगा।"],
"adm.rv_done_on": ["Review access is on for {email}. Sample bill {ref}.", "{email} के लिए समीक्षा पहुँच चालू है। नमूना बिल {ref}।"],
"adm.rv_done_off": ["Review access is off. The sample bill was cancelled.", "समीक्षा पहुँच बंद है। नमूना बिल रद्द कर दिया गया।"],
"adm.rv_e_REQUIRED": ["Enter the Google account's email.", "Google खाते का ईमेल लिखें।"],
"adm.rv_e_FORMAT": ["Enter a full email address, such as grieviq.review@gmail.com.", "पूरा ईमेल पता लिखें, जैसे grieviq.review@gmail.com।"],
"adm.rv_e_IN_USE": ["This email is already used in GrievIQ by a real office, team member, officer, official or staff member. Make a new Gmail just for the reviewers.", "यह ईमेल GrievIQ में पहले से किसी असली कार्यालय, टीम सदस्य, अधिकारी, सरकारी उपयोगकर्ता या स्टाफ़ द्वारा उपयोग हो रहा है। समीक्षकों के लिए एक नया Gmail बनाएँ।"],
"adm.qt_h": ["Quotations", "कोटेशन"],
"adm.qt_p": ["For an office that needs a formal price for its file before ordering. The price comes from the published prices and stays fixed until the valid-until date. Send it by email with a private link, or open it to print or save as a PDF. When the office's order arrives, turn it into a bill at the quoted price.", "उस कार्यालय के लिए जिसे आदेश से पहले अपनी फ़ाइल हेतु औपचारिक मूल्य चाहिए। मूल्य प्रकाशित शुल्क से आता है और मान्यता तिथि तक वही रहता है। इसे निजी लिंक के साथ ईमेल करें, या प्रिंट करने या PDF सहेजने के लिए खोलें। कार्यालय का आदेश आने पर इसे कोटेशन मूल्य पर बिल में बदलें।"],
"adm.qt_new_h": ["Make a quotation", "कोटेशन बनाएँ"],
"adm.qt_office": ["Office name (as it should appear)", "कार्यालय का नाम (जैसा दिखना चाहिए)"],
"adm.qt_to": ["Addressed to (optional), e.g. The Executive Engineer", "सेवा में (वैकल्पिक), जैसे अधिशासी अभियंता"],
