"adm.qt_open": ["Open, print or save {ref} as PDF (opens in a new tab)", "{ref} खोलें, प्रिंट करें या PDF सहेजें (नए टैब में खुलता है)"],
"adm.qt_email_to": ["Office email", "कार्यालय का ईमेल"],
"adm.qt_email_btn": ["Email the quotation", "कोटेशन ईमेल करें"],
"adm.qt_accept_btn": ["Order received: make the bill", "आदेश प्राप्त: बिल बनाएँ"],
"adm.qt_accept_p": ["Choose the office on GrievIQ that ordered, write the order number and the start date. The bill is made at the quoted total of {t} and emailed to the office.", "आदेश देने वाला GrievIQ कार्यालय चुनें, आदेश संख्या और आरंभ तिथि लिखें। बिल {t} की कोटेशन राशि पर बनता है और कार्यालय को ईमेल होता है।"],
