"adm.qt_done_accept": ["Bill {bill} made at the quoted {t} and sent to the office.", "बिल {bill} कोटेशन राशि {t} पर बना और कार्यालय को भेजा गया।"],
"adm.qt_e_expired": ["This quotation has expired. Make a new one at today's prices.", "इस कोटेशन की अवधि समाप्त हो गई है। आज के शुल्क पर नया बनाएँ।"],
