"adm.qt_e_from_TWICE": ["This office already has a bill starting that day.", "इस कार्यालय का उस दिन से शुरू होने वाला बिल पहले से है।"],
"adm.qt_c_group": ["Priced on request (super admin)", "अनुरोध पर मूल्य (सुपर एडमिन)"],
"adm.qt_c_wait": ["Type the yearly price to see GST and the total.", "GST और कुल राशि देखने के लिए वार्षिक मूल्य लिखें।"],
"adm.qt_c_note": ["Priced on request: you type the yearly price, before GST. Write the scope it covers (shown on the quotation) and why this price (kept for the auditor, never shown to the buyer).", "अनुरोध पर मूल्य: आप GST से पहले का वार्षिक मूल्य लिखते हैं। इसका दायरा लिखें (कोटेशन पर दिखता है) और यह मूल्य क्यों (ऑडिटर के लिए रखा जाता है, क्रेता को कभी नहीं दिखता)।"],
