"adm.qt_c_accept_p": ["Write the order number (work order, purchase order or sanction letter). The order for {t} is recorded on the quotation; invoice it outside GrievIQ's bills (GST tax invoice).", "आदेश संख्या लिखें (कार्य आदेश, क्रय आदेश या स्वीकृति पत्र)। {t} का आदेश कोटेशन पर दर्ज होता है; इसका बीजक GrievIQ के बिलों के बाहर बनाएँ (GST कर बीजक)।"],
