"bill.h_utr": ["From your UPI app or bank: the 12-digit UPI reference, or the UTR of the transfer.", "अपने UPI ऐप या बैंक से: 12 अंकों का UPI संदर्भ, या ट्रांसफ़र का UTR।"],
"bill.f_amount": ["Amount paid (₹)", "भुगतान की गई राशि (₹)"],
