"bill.send": ["Send payment details", "भुगतान विवरण भेजें"],
"bill.e_h": ["Please fix {n} thing(s):", "कृपया {n} बात(ें) ठीक करें:"],
"bill.e_method_REQUIRED": ["Choose how you paid.", "भुगतान का माध्यम चुनें।"],
"bill.e_utr_REQUIRED": ["Enter the transaction reference.", "लेन-देन संदर्भ लिखें।"],
"bill.e_utr_FORMAT": ["Enter only the letters and numbers of the reference (10 to 22).", "संदर्भ के केवल अक्षर और अंक लिखें (10 से 22)।"],
