"bp.how": ["sign in at grieviq.in and open Billing: pay online, or pay by UPI or bank transfer to the details shown there only.", "grieviq.in पर साइन इन करके बिलिंग खोलें: ऑनलाइन भुगतान करें, या केवल वहीं दिखाए विवरण पर UPI या बैंक ट्रांसफ़र से भुगतान करें।"],
"bp.same": ["Every office pays the same published price. Payments by a political party or an election campaign are not accepted.", "हर कार्यालय समान प्रकाशित शुल्क देता है। किसी राजनीतिक दल या चुनाव अभियान द्वारा भुगतान स्वीकार नहीं किया जाता।"],
"bp.policies": ["Refunds and cancellation: grieviq.in/refunds · Service delivery: grieviq.in/delivery", "धनवापसी और रद्दीकरण: grieviq.in/refunds · सेवा प्रदान करना: grieviq.in/delivery"],
"bp.e_link": ["This link isn't complete. Open the bill again from Billing.", "यह लिंक अधूरा है। बिलिंग से बिल फिर से खोलें।"],
"bp.e_access": ["Please sign in first, then open the bill again from Billing.", "कृपया पहले साइन इन करें, फिर बिलिंग से बिल दोबारा खोलें।"],
"bp.e_none": ["This bill isn't one you can see.", "यह बिल आपके देखने के लिए नहीं है।"],
"bp.e_load": ["The bill couldn't be loaded. Please reload the page.", "बिल लोड नहीं हो सका। कृपया पृष्ठ फिर से लोड करें।"],
"bill.print": ["Print or save as PDF", "प्रिंट करें या PDF सहेजें"],
