"adm.hl_flag_SIMILAR_TEXT_l": ["Flag: the description is very like another this helper filed in the last 30 days.", "चिह्न: विवरण इस सहायक द्वारा पिछले 30 दिनों में दर्ज किसी अन्य से बहुत मिलता है।"],
"adm.hl_flag_SAME_PHONE_l": ["Flag: this helper has filed for the same citizen mobile 3 or more times in 30 days.", "चिह्न: इस सहायक ने 30 दिनों में एक ही नागरिक मोबाइल के लिए 3 या अधिक बार दर्ज किया।"],
"adm.hl_removed_DIDNT_ASK": ["removed by the citizen: didn't ask", "नागरिक ने हटाया: नहीं कहा था"],
