"adm.hl_calls_p": ["The citizen has no email, or didn't confirm by email in 3 days. Call them, read out what was filed, and ask if they asked the helper to file it. Nothing reaches the representative until they say yes.", "नागरिक का ईमेल नहीं है, या उन्होंने 3 दिनों में ईमेल से पुष्टि नहीं की। उन्हें कॉल करें, जो दर्ज हुआ वह पढ़कर सुनाएँ, और पूछें कि क्या उन्होंने सहायक से यह दर्ज करने को कहा था। उनके हाँ कहने तक जनप्रतिनिधि तक कुछ नहीं पहुँचता।"],
"adm.hl_flagged_h": ["Flagged helper filings", "चिह्नित सहायक शिकायतें"],
