"adm.hl_call_tries": ["{n} call(s) without an answer", "{n} कॉल बिना उत्तर"],
"adm.hl_call_mobile": ["Citizen's mobile:", "नागरिक का मोबाइल:"],
"adm.hl_show_phone": ["Show the full number", "पूरा नंबर दिखाएँ"],
"adm.hl_show_phone_note": ["Showing the number is recorded with your name.", "नंबर दिखाना आपके नाम के साथ दर्ज होता है।"],
