"adm.hl_call_NOT_ASKED": ["They didn't ask the helper (a strike)", "उन्होंने सहायक से नहीं कहा था (एक चेतावनी)"],
"adm.hl_note_opt": ["Note (optional)", "टिप्पणी (वैकल्पिक)"],
