"adm.hl_flag_FAKE": ["False filing (a strike; dropped if still waiting)", "झूठी शिकायत (एक चेतावनी; प्रतीक्षा में हो तो हटा दी जाएगी)"],
"adm.hl_flag_note_h": ["Needed for a false filing (10 to 500 characters). Staff only.", "झूठी शिकायत के लिए आवश्यक (10 से 500 अक्षर)। केवल स्टाफ़ के लिए।"],
