"adm.hl_ok_call": ["Call recorded.", "कॉल दर्ज की गई।"],
"adm.hl_ok_flag": ["Recorded.", "दर्ज किया गया।"],
"adm.hl_e_CANT_FILE": ["It couldn't be filed: the ward can't take complaints now. Nothing was sent.", "दर्ज नहीं हो सकी: वार्ड अभी शिकायतें नहीं ले सकता। कुछ नहीं भेजा गया।"],
