"adm.hl_ev_FILING_SENT": ["Citizen confirmed: sent", "नागरिक ने पुष्टि की: भेजी गई"],
"adm.hl_ev_FILING_NOT_ASKED": ["Citizen didn't ask", "नागरिक ने नहीं कहा था"],
