"hp.blocked_IS_STAFF": ["GrievIQ staff can't be Community helpers.", "GrievIQ स्टाफ़ सामुदायिक सहायक नहीं बन सकते।"],
"hp.not_set_up": ["Applications can't be taken just now. Please try again later.", "अभी आवेदन नहीं लिए जा सकते। कृपया बाद में प्रयास करें।"],
"hp.form_h": ["Apply to be a Community helper", "सामुदायिक सहायक बनने के लिए आवेदन करें"],
"hp.form_p": ["Everything you send is seen only by GrievIQ staff. Your name is never shown publicly: people see only your helper number.", "आप जो भी भेजते हैं, उसे केवल GrievIQ स्टाफ़ देखता है। आपका नाम कभी सार्वजनिक नहीं होता: लोगों को केवल आपका सहायक नंबर दिखता है।"],
"hp.req_note": ["All questions are needed unless marked optional.", "जब तक वैकल्पिक न लिखा हो, सभी प्रश्न आवश्यक हैं।"],
