"hp.f_about": ["About your local work (optional)", "आपके स्थानीय काम के बारे में (वैकल्पिक)"],
"hp.h_about": ["For example: \"I run a shop near the market.\" Up to {n} characters. Seen by staff only.", "उदाहरण: \"मेरी बाज़ार के पास दुकान है।\" अधिकतम {n} अक्षर। केवल स्टाफ़ देखता है।"],
