"hp.h_id_PAN": ["10 characters, like ABCDE1234F.", "10 अक्षर, जैसे ABCDE1234F।"],
"hp.h_id_DL": ["As printed, like UP14 20110012345.", "जैसा छपा है, जैसे UP14 20110012345।"],
"hp.h_id_PASSPORT": ["1 letter and 7 digits, like K1234567.", "1 अक्षर और 7 अंक, जैसे K1234567।"],
"hp.h_id_AADHAAR": ["Only the last 4 digits. Never type the full Aadhaar number.", "केवल अंतिम 4 अंक। पूरा आधार नंबर कभी न लिखें।"],
"hp.h_id_keep": ["GrievIQ keeps only the ID type and its last 4 characters, plus a coded check that stops the same ID being used twice.", "GrievIQ केवल पहचान पत्र का प्रकार और उसके अंतिम 4 अक्षर रखता है, साथ में एक कूटबद्ध जाँच जो एक ही पहचान पत्र के दो बार उपयोग को रोकती है।"],
"hp.f_idPhoto": ["Photo of your ID (front)", "आपके पहचान पत्र की फ़ोटो (सामने की ओर)"],
"hp.h_idPhoto": ["The whole card, clear and readable. For Aadhaar, use the masked card (only the last 4 digits showing).", "पूरा कार्ड, साफ़ और पढ़ने योग्य। आधार के लिए मास्क्ड कार्ड लगाएँ (केवल अंतिम 4 अंक दिखें)।"],
"hp.f_selfie": ["Selfie holding the same ID", "उसी पहचान पत्र को पकड़े हुए सेल्फ़ी"],
"hp.h_selfie": ["Your face and the ID both clearly visible.", "आपका चेहरा और पहचान पत्र दोनों साफ़ दिखें।"],
"hp.h_photos": ["Photos are made smaller on your phone before sending. They are deleted 30 days after the decision, and every time staff open them is recorded.", "भेजने से पहले फ़ोटो आपके फ़ोन पर छोटी की जाती हैं। निर्णय के 30 दिन बाद उन्हें हटा दिया जाता है, और स्टाफ़ जब भी उन्हें खोलता है, यह दर्ज होता है।"],
"hp.photo_kept": ["A photo is already saved. Choose a new one only to replace it.", "एक फ़ोटो पहले से सहेजी है। उसे बदलना हो तभी नई चुनें।"],
"hp.conduct_h": ["Code of conduct", "आचार संहिता"],
"hp.conduct1": ["I will help only when a citizen asks me, and file only what they tell me.", "मैं केवल नागरिक के कहने पर मदद करूँगा/करूँगी, और केवल वही दर्ज करूँगा/करूँगी जो वे बताएँ।"],
"hp.conduct2": ["I will never ask for or take money, gifts or favours from citizens.", "मैं नागरिकों से कभी पैसे, उपहार या कोई लाभ नहीं माँगूँगा/माँगूँगी, न लूँगा/लूँगी।"],
"hp.conduct3": ["I will not speak for any political party or candidate, or use GrievIQ in any campaign.", "मैं किसी राजनीतिक दल या प्रत्याशी की ओर से नहीं बोलूँगा/बोलूँगी, न किसी अभियान में GrievIQ का उपयोग करूँगा/करूँगी।"],
"hp.conduct4": ["I will keep citizens' details private and use them only for their complaint.", "मैं नागरिकों का विवरण गोपनीय रखूँगा/रखूँगी और केवल उनकी शिकायत के लिए उपयोग करूँगा/करूँगी।"],
"hp.conduct5": ["I will not file false, repeated or abusive complaints.", "मैं झूठी, दोहराई गई या अपमानजनक शिकायतें दर्ज नहीं करूँगा/करूँगी।"],
"hp.conduct6": ["I understand GrievIQ can suspend or remove me for breaking these rules, and that paying the fee doesn't protect me from that.", "मैं समझता/समझती हूँ कि इन नियमों के उल्लंघन पर GrievIQ मुझे निलंबित कर सकता है या हटा सकता है, और शुल्क देने से इससे सुरक्षा नहीं मिलती।"],
"hp.f_conduct": ["I agree to the code of conduct", "मैं आचार संहिता से सहमत हूँ"],
"hp.save": ["Save and continue to payment", "सहेजें और भुगतान पर जाएँ"],
