"hp.e_FORMAT": ["Please check how this is written.", "कृपया जाँचें कि यह कैसे लिखा है।"],
"hp.e_LENGTH": ["This is too long.", "यह बहुत लंबा है।"],
"hp.e_SHORT": ["Please write a little more.", "कृपया थोड़ा और लिखें।"],
"hp.e_UNKNOWN": ["Choose your ward or village from the list.", "सूची से अपना वार्ड या गाँव चुनें।"],
"hp.e_USED": ["This ID is already linked to another Google account. Write to support if this is a mistake.", "यह पहचान पत्र पहले से किसी अन्य Google खाते से जुड़ा है। यदि यह गलती है तो सहायता को लिखें।"],
"hp.e_FULL_AADHAAR": ["Never send the full Aadhaar number. Choose Aadhaar and type only the last 4 digits.", "पूरा आधार नंबर कभी न भेजें। आधार चुनें और केवल अंतिम 4 अंक लिखें।"],
