"hp.e_conduct_REQUIRED": ["Please tick to agree to the code of conduct.", "कृपया आचार संहिता से सहमति के लिए टिक करें।"],
"hp.e_text_SHORT": ["Please write at least 20 characters.", "कृपया कम से कम 20 अक्षर लिखें।"],
"hp.e_CLOSED": ["Applications are not open at the moment.", "अभी आवेदन खुले नहीं हैं।"],
"hp.e_ALREADY": ["You already have an application or a helper role.", "आपका पहले से एक आवेदन या सहायक की भूमिका है।"],
"hp.e_ELECTION_PAUSE": ["Applications and payments are paused in this area while the election code is in force.", "चुनाव आचार संहिता लागू रहने तक इस क्षेत्र में आवेदन और भुगतान रुके हैं।"],
"hp.e_NOT_ALLOWED": ["This account or ID can't be used for a new application. Write to support if you think this is a mistake.", "इस खाते या पहचान पत्र से नया आवेदन नहीं किया जा सकता। यदि आपको लगता है यह गलती है, तो सहायता को लिखें।"],
