"hp.draft_p": ["It is sent to GrievIQ when the first month is paid. Applications not paid for are deleted after 30 days.", "पहले महीने का भुगतान होने पर यह GrievIQ को भेजा जाता है। बिना भुगतान वाले आवेदन 30 दिन बाद हटा दिए जाते हैं।"],
