"hp.pay_first_p": ["₹{price} for the first month (GST included). Your month starts on the day you are approved. The fee is refunded in full if you are refused for a reason that isn't your fault, or if you withdraw before the decision.", "पहले महीने के लिए ₹{price} (GST सहित)। आपका महीना स्वीकृति के दिन से शुरू होता है। यदि ऐसे कारण से अस्वीकृत हों जिसमें आपकी गलती नहीं, या निर्णय से पहले आवेदन वापस लें, तो पूरा शुल्क लौटाया जाता है।"],
"hp.pay_how": ["Razorpay's secure window opens for UPI, card or net banking. Your card or UPI details go to Razorpay only, never to GrievIQ.", "UPI, कार्ड या नेट बैंकिंग के लिए Razorpay की सुरक्षित विंडो खुलती है। आपके कार्ड या UPI का विवरण केवल Razorpay को जाता है, कभी GrievIQ को नहीं।"],
"hp.own": ["I am paying from my own money, not with money from a political party or an election campaign.", "मैं अपने पैसे से भुगतान कर रहा/रही हूँ, किसी राजनीतिक दल या चुनाव अभियान के पैसे से नहीं।"],
"hp.own_e": ["Please tick this to pay.", "भुगतान के लिए कृपया इसे टिक करें।"],
"hp.pay_btn": ["Pay ₹{price} and send", "₹{price} का भुगतान करें और भेजें"],
"hp.renew_h": ["Pay the next month", "अगले महीने का भुगतान करें"],
"hp.renew_p": ["₹{price} (GST included). The new month carries on from your paid-up date.", "₹{price} (GST सहित)। नया महीना आपकी भुगतान तिथि के बाद से जारी रहता है।"],
"hp.renew_p_lapsed": ["₹{price} (GST included). Your new month starts today.", "₹{price} (GST सहित)। आपका नया महीना आज से शुरू होगा।"],
"hp.renew_btn": ["Pay ₹{price}", "₹{price} का भुगतान करें"],
"hp.opening": ["Opening the payment window…", "भुगतान विंडो खुल रही है…"],
"hp.checking": ["Checking the payment with Razorpay…", "Razorpay से भुगतान की जाँच हो रही है…"],
"hp.test": ["Test mode: no money moves.", "टेस्ट मोड: कोई पैसा नहीं जाता।"],
"hp.pay_test_paid": ["Test payment done. No money moved and nothing was sent.", "टेस्ट भुगतान हुआ। कोई पैसा नहीं गया और कुछ नहीं भेजा गया।"],
"hp.pay_waiting": ["Your payment is being confirmed. This page shows it once it is; you can close it meanwhile.", "आपके भुगतान की पुष्टि हो रही है। पुष्टि होते ही यह पृष्ठ दिखाएगा; तब तक आप इसे बंद कर सकते हैं।"],
"hp.pay_closed": ["The payment window was closed. Nothing was paid.", "भुगतान विंडो बंद कर दी गई। कोई भुगतान नहीं हुआ।"],
"hp.pay_failed": ["Payment failed: {why}. Nothing was taken. You can try again.", "भुगतान विफल: {why}। कोई पैसा नहीं कटा। आप फिर प्रयास कर सकते हैं।"],
"hp.pay_extra": ["Your payment was received but couldn't be used. GrievIQ will refund it.", "आपका भुगतान मिला पर उपयोग नहीं हो सका। GrievIQ इसे लौटा देगा।"],
"hp.paid_sent": ["Paid. Your application has been sent to GrievIQ.", "भुगतान हो गया। आपका आवेदन GrievIQ को भेज दिया गया।"],
