"hp.e_ONLINE_OFF": ["Online payment isn't available just now. Please try again later.", "ऑनलाइन भुगतान अभी उपलब्ध नहीं है। कृपया बाद में प्रयास करें।"],
"hp.e_TOO_MANY": ["Too many tries today. Please try again tomorrow.", "आज बहुत अधिक प्रयास हुए। कृपया कल फिर प्रयास करें।"],
"hp.e_NOT_YET": ["The next month can be paid from 10 days before this one ends.", "अगले महीने का भुगतान इस महीने के समाप्त होने से 10 दिन पहले से किया जा सकता है।"],
"hp.e_NOT_NOW": ["Nothing to pay just now.", "अभी कोई भुगतान नहीं करना है।"],
"hp.e_window": ["The payment window couldn't open. Please check your connection and try again.", "भुगतान विंडो नहीं खुल सकी। कृपया अपना कनेक्शन जाँचें और फिर प्रयास करें।"],
"hp.e_BAD_PAYMENT": ["The payment couldn't be confirmed. If money was taken, it will be checked within an hour.", "भुगतान की पुष्टि नहीं हो सकी। यदि पैसा कटा है, तो एक घंटे में उसकी जाँच होगी।"],
"hp.wait_h": ["Your application is being checked", "आपके आवेदन की जाँच हो रही है"],
