"hp.wait2": ["ID and selfie check, and a short video call. GrievIQ staff will phone or email you to fix a time.", "पहचान पत्र और सेल्फ़ी की जाँच, और एक छोटी वीडियो कॉल। समय तय करने के लिए GrievIQ स्टाफ़ आपको फ़ोन या ईमेल करेगा।"],
"hp.wait3": ["Decision by a different staff member", "किसी अन्य स्टाफ़ सदस्य द्वारा निर्णय"],
