"hp.withdraw": ["Withdraw application", "आवेदन वापस लें"],
"hp.withdraw_q": ["Withdraw your application? Your photos are deleted and the fee is refunded in full.", "अपना आवेदन वापस लें? आपकी फ़ोटो हटा दी जाएँगी और पूरा शुल्क लौटाया जाएगा।"],
"hp.withdraw_yes": ["Yes, withdraw", "हाँ, वापस लें"],
"hp.withdrawn_ok": ["Application withdrawn. The fee will be refunded in full, usually within 5–7 working days.", "आवेदन वापस लिया गया। पूरा शुल्क आमतौर पर 5–7 कार्य दिवसों में लौटाया जाएगा।"],
"hp.card_label": ["Community helper", "सामुदायिक सहायक"],
