"hp.grace": ["Your month ended on {date}. Please pay by {grace} to carry on.", "आपका महीना {date} को समाप्त हुआ। जारी रखने के लिए कृपया {grace} तक भुगतान करें।"],
"hp.lapsed": ["Your helper role is paused because the month's fee wasn't paid. Pay to start again today.", "महीने का शुल्क न देने के कारण आपकी सहायक की भूमिका रुकी हुई है। आज से फिर शुरू करने के लिए भुगतान करें।"],
"hp.pause": ["Paused while the election code is in force in your area (until {date}). These days are added to your month.", "आपके क्षेत्र में चुनाव आचार संहिता लागू रहने तक रुका हुआ ({date} तक)। ये दिन आपके महीने में जोड़ दिए जाते हैं।"],
"hp.renew_soon": ["Your month ends on {date}. You can pay the next month now.", "आपका महीना {date} को समाप्त होगा। आप अभी अगले महीने का भुगतान कर सकते हैं।"],
"hp.kyc_h": ["Yearly ID check", "वार्षिक पहचान जाँच"],
"hp.kyc_p": ["Every helper's ID is checked again once a year. Please send a new photo of your ID and a selfie holding it by {date}.", "हर सहायक का पहचान पत्र साल में एक बार फिर जाँचा जाता है। कृपया {date} तक अपने पहचान पत्र की नई फ़ोटो और उसे पकड़े हुए सेल्फ़ी भेजें।"],
"hp.kyc_over": ["Your yearly ID check is overdue, so your helper role is paused until it is done.", "आपकी वार्षिक पहचान जाँच की तिथि निकल चुकी है, इसलिए जाँच पूरी होने तक आपकी सहायक की भूमिका रुकी हुई है।"],
"hp.kyc_send": ["Send for checking", "जाँच के लिए भेजें"],
"hp.kyc_wait": ["Your yearly ID check is with GrievIQ staff.", "आपकी वार्षिक पहचान जाँच GrievIQ स्टाफ़ के पास है।"],
"hp.kyc_sent": ["Sent. GrievIQ staff will check it.", "भेज दिया गया। GrievIQ स्टाफ़ इसकी जाँच करेगा।"],
"hp.stop_h": ["Stop being a helper", "सहायक की भूमिका छोड़ें"],
"hp.stop_p": ["Your number will show as not active. Part-months are not refunded. You can apply again later.", "आपका नंबर सक्रिय नहीं दिखेगा। अधूरे महीने का शुल्क नहीं लौटाया जाता। आप बाद में फिर आवेदन कर सकते हैं।"],
