"adm.hl_page_title": ["GrievIQ Admin — Community helpers", "GrievIQ एडमिन — सामुदायिक सहायक"],
"adm.hl_sub": ["Applications to check and approve, helpers, appeals and refunds.", "जाँचने और स्वीकृत करने के आवेदन, सहायक, अपीलें और धनवापसी।"],
"adm.hl_note": ["One staff member <b>checks</b> (ID photo, selfie and a video call); a <b>different</b> senior staff member <b>approves</b>. Every time an ID photo or selfie is opened, it is recorded in the helper's history; the photos are deleted 30 days after the decision. The applicant sees the reason for a refusal, suspension or removal, so write it about the application or conduct only. A helper's name is never shown publicly.", "एक स्टाफ़ सदस्य <b>जाँच</b> करता है (पहचान पत्र की फ़ोटो, सेल्फ़ी और वीडियो कॉल); कोई <b>अन्य</b> वरिष्ठ स्टाफ़ सदस्य <b>स्वीकृत</b> करता है। पहचान पत्र की फ़ोटो या सेल्फ़ी जब भी खोली जाती है, सहायक के इतिहास में दर्ज होती है; फ़ोटो निर्णय के 30 दिन बाद हटा दी जाती हैं। आवेदक अस्वीकृति, निलंबन या हटाए जाने का कारण देखता है, इसलिए कारण केवल आवेदन या आचरण के बारे में लिखें। सहायक का नाम कभी सार्वजनिक नहीं होता।"],
"adm.hl_e_load": ["Community helpers couldn't be loaded. Please reload the page.", "सामुदायिक सहायक लोड नहीं हो सके। कृपया पृष्ठ फिर से लोड करें।"],
"adm.hl_not_ready": ["This page needs the database step part46 first.", "इस पृष्ठ के लिए पहले डेटाबेस चरण part46 आवश्यक है।"],
"adm.hl_not_set_up": ["Applications can't be taken yet: the HELPER_ID_SECRET secret or the private photo storage is missing (Help → Community helpers).", "अभी आवेदन नहीं लिए जा सकते: HELPER_ID_SECRET सीक्रेट या निजी फ़ोटो भंडारण नहीं है (सहायता → सामुदायिक सहायक)।"],
