"adm.sb_pause_q": ["Make {name} view only? Citizens' complaints still reach the office and move up on time.", "{name} को केवल देखने वाला बनाएँ? नागरिकों की शिकायतें फिर भी कार्यालय पहुँचेंगी और समय पर ऊपर जाएँगी।"],
"adm.sb_end_q": ["End access for {name}? Its team will not be able to sign in. Citizens' complaints still move up on time.", "{name} की पहुँच समाप्त करें? उसकी टीम साइन इन नहीं कर पाएगी। नागरिकों की शिकायतें फिर भी समय पर ऊपर जाएँगी।"],
