"rep.plan_due": ["The plan for {office} is paid up to {date}. The next bill will appear in Billing.", "{office} की योजना {date} तक है। अगला बिल बिलिंग में दिखेगा।"],
"rep.plan_pilot_end": ["The free pilot for {office} ends on {date}. GrievIQ will contact you about a plan.", "{office} का निःशुल्क पायलट {date} को समाप्त होगा। GrievIQ योजना के बारे में आपसे संपर्क करेगा।"],
"rep.plan_grace_t": ["The plan for {office} ended on {date}.", "{office} की योजना {date} को समाप्त हुई।"],
"rep.plan_grace_b": ["Everything keeps working until {date}. After that the console becomes view only until the bill is paid.", "{date} तक सब कुछ चलता रहेगा। उसके बाद बिल चुकाने तक कंसोल केवल देखने के लिए रहेगा।"],
"rep.plan_paused_t": ["{office}: your office's plan is paused (view only).", "{office}: आपके कार्यालय की योजना रुकी है (केवल देखना)।"],
"rep.plan_paused_b": ["Complaints still reach you and move up to the next level on time. You can see them, read messages and reply to the auditor, but not act on complaints.", "शिकायतें आपको मिलती रहेंगी और समय पर अगले स्तर पर जाएँगी। आप उन्हें देख सकते हैं, संदेश पढ़ सकते हैं और ऑडिटर को उत्तर दे सकते हैं, पर शिकायतों पर कार्रवाई नहीं कर सकते।"],
"rep.plan_paused_admin": ["GrievIQ paused it. Please write to support@grieviq.in.", "इसे GrievIQ ने रोका है। कृपया support@grieviq.in पर लिखें।"],
"rep.plan_paused_ask": ["Please ask your representative or office manager.", "कृपया अपने प्रतिनिधि या कार्यालय प्रबंधक से पूछें।"],
"rep.plan_pay": ["Pay to continue →", "जारी रखने के लिए भुगतान करें →"],
"rep.plan_open": ["Open Billing →", "बिलिंग खोलें →"],
"rep.plan_case_paused": ["Your office's plan is paused, so this complaint can only be viewed. It still moves up on time.", "आपके कार्यालय की योजना रुकी है, इसलिए यह शिकायत केवल देखी जा सकती है। यह फिर भी समय पर ऊपर जाएगी।"],
"dd.plan_due": ["Your office's plan is paid up to {date}. The next bill will appear in Billing.", "आपके कार्यालय की योजना {date} तक है। अगला बिल बिलिंग में दिखेगा।"],
"dd.plan_pilot_end": ["Your office's free pilot ends on {date}. GrievIQ will contact you about a plan.", "आपके कार्यालय का निःशुल्क पायलट {date} को समाप्त होगा। GrievIQ योजना के बारे में आपसे संपर्क करेगा।"],
"dd.plan_grace_t": ["Your office's plan ended on {date}.", "आपके कार्यालय की योजना {date} को समाप्त हुई।"],
"dd.plan_paused_t": ["Your office's plan is paused (view only).", "आपके कार्यालय की योजना रुकी है (केवल देखना)।"],
"dd.plan_paused_b": ["Complaints still reach you and move up on time if not handled. You can see them and pay, but not reply.", "शिकायतें आपको मिलती रहेंगी और निपटाई न जाने पर समय पर ऊपर जाएँगी। आप उन्हें देख और भुगतान कर सकते हैं, पर उत्तर नहीं दे सकते।"],
"dd.plan_case_paused": ["Your office's plan is paused, so you can't reply. The complaint still moves up on time.", "आपके कार्यालय की योजना रुकी है, इसलिए आप उत्तर नहीं दे सकते। शिकायत फिर भी समय पर ऊपर जाएगी।"],
"adm.nav_speed": ["Speed", "गति"],
"adm.sp_page_title": ["GrievIQ Admin — Speed", "GrievIQ एडमिन — गति"],
"adm.sp_sub": ["How quickly GrievIQ answers. The target: 95 of every 100 requests answered within 0.5 seconds.", "GrievIQ कितनी जल्दी उत्तर देता है। लक्ष्य: हर 100 में से 95 अनुरोधों का उत्तर 0.5 सेकंड के भीतर।"],
"adm.sp_how_h": ["How this is measured", "यह कैसे मापा जाता है"],
"adm.sp_how_body": ["About 1 in every 20 requests to GrievIQ's servers records how long it took. No person, address or complaint is recorded. Every hour the figures are worked out for each part of GrievIQ and kept for 30 days. If a part is slow for 2 hours in a row, every super admin gets one email that day.", "GrievIQ के सर्वर पर लगभग हर 20 में से 1 अनुरोध का लगा समय दर्ज होता है। कोई व्यक्ति, पता या शिकायत दर्ज नहीं होती। हर घंटे GrievIQ के हर हिस्से के आँकड़े निकाले जाते हैं और 30 दिन रखे जाते हैं। कोई हिस्सा लगातार 2 घंटे धीमा रहे तो हर सुपर एडमिन को उस दिन एक ईमेल जाता है।"],
"adm.sp_not_ready": ["The speed monitor is not set up yet: run the part31 database step.", "गति निगरानी अभी तैयार नहीं: part31 डेटाबेस चरण चलाएँ।"],
"adm.sp_st_FAST": ["Fast", "तेज़"],
"adm.sp_st_GETTING_SLOWER": ["Getting slower", "धीमा हो रहा है"],
"adm.sp_st_SLOW": ["Slow", "धीमा"],
"adm.sp_st_NO_DATA": ["Not enough traffic yet", "अभी पर्याप्त उपयोग नहीं"],
"adm.sp_st_FAST_h": ["Every part of GrievIQ met the 0.5-second target in the last 2 hours.", "पिछले 2 घंटों में GrievIQ के हर हिस्से ने 0.5 सेकंड का लक्ष्य पूरा किया।"],
"adm.sp_st_GETTING_SLOWER_h": ["Slower than the target in the last hour: {parts}. If it stays slow for another hour, super admins are emailed.", "पिछले घंटे लक्ष्य से धीमा: {parts}। एक घंटा और धीमा रहा तो सुपर एडमिन को ईमेल जाएगा।"],
"adm.sp_st_SLOW_h": ["Slower than the target for 2 hours in a row: {parts}. Ask your developer to look at it; the steps are in the help guide.", "लगातार 2 घंटे से लक्ष्य से धीमा: {parts}। अपने डेवलपर से जाँच करवाएँ; चरण सहायता गाइड में हैं।"],
