"adm.it_theme_note": ["The <b>theme</b> groups issue types the way ISO 37120 groups city services (water, energy, transport and so on), so the government dashboard can compare like with like. It changes nothing for citizens or offices.", "<b>विषय</b> समस्या के प्रकारों को उसी तरह समूहित करता है जैसे ISO 37120 शहरी सेवाओं को (जल, ऊर्जा, परिवहन आदि), ताकि सरकारी डैशबोर्ड एक जैसी चीज़ों की तुलना कर सके। नागरिकों या कार्यालयों के लिए कुछ नहीं बदलता।"],
