"adm.nav_gov": ["Government access", "सरकारी पहुँच"],
"adm.gv_page_title": ["GrievIQ Admin — Government access", "GrievIQ एडमिन — सरकारी पहुँच"],
"adm.gv_sub": ["Officials of a Union ministry, a state or a district who may open GrievIQ's government dashboard, what they opened, and the representatives' offices that chose to share their own figures.", "किसी केंद्रीय मंत्रालय, राज्य या ज़िले के अधिकारी जो GrievIQ का सरकारी डैशबोर्ड खोल सकते हैं, उन्होंने क्या खोला, और जनप्रतिनिधियों के वे कार्यालय जिन्होंने अपने आँकड़े साझा करना चुना।"],
"adm.gv_note": ["<b>The rules:</b> access only on a letter from the state government, to an official email (gov.in or nic.in), or to another email the letter names, as a recorded exception; reviewed every year (every 90 days for another email). Officials see government departments in full, but representatives' offices only as totals for each district, unless an office chooses to share. No citizen's name, phone number or complaint text is ever shown.", "<b>नियम:</b> पहुँच केवल राज्य सरकार के पत्र पर, आधिकारिक ईमेल (gov.in या nic.in) पर, या पत्र में लिखे दूसरे ईमेल पर दर्ज अपवाद के रूप में; हर साल समीक्षा (दूसरे ईमेल के लिए हर 90 दिन)। अधिकारी सरकारी विभागों को पूरा देखते हैं, पर जनप्रतिनिधियों के कार्यालयों को केवल हर ज़िले के कुल योग के रूप में, जब तक कोई कार्यालय साझा करना न चुने। किसी नागरिक का नाम, फ़ोन नंबर या शिकायत का पाठ कभी नहीं दिखाया जाता।"],
"adm.gv_not_ready": ["Government access isn't set up yet. Run the database update part32-gov.sql.", "सरकारी पहुँच अभी तैयार नहीं है। डेटाबेस अपडेट part32-gov.sql चलाएँ।"],
"adm.gv_new_h": ["Give an official access", "किसी अधिकारी को पहुँच दें"],
"adm.gv_new_p": ["Only after the state government's letter naming this person has reached you. Keep the letter: its number and date are recorded here.", "केवल तब, जब इस व्यक्ति का नाम लिखा राज्य सरकार का पत्र आपको मिल जाए। पत्र सँभालकर रखें: उसका नंबर और तारीख़ यहाँ दर्ज होती है।"],
"adm.gv_fix_h": ["Please check these", "कृपया इन्हें जाँचें"],
