"adm.gv_f_designation": ["Designation", "पदनाम"],
"adm.gv_f_designation_h": ["For example: Principal Secretary, Public Grievances; District Magistrate", "उदाहरण: प्रमुख सचिव, जन शिकायत; ज़िलाधिकारी"],
