"adm.gv_share_p": ["Only the office's representative can choose this, in the Team tab of their console. All other representatives' offices appear only inside district totals.", "यह केवल कार्यालय के जनप्रतिनिधि अपने कंसोल के टीम टैब में चुन सकते हैं। बाकी सभी जनप्रतिनिधियों के कार्यालय केवल ज़िले के कुल योग में आते हैं।"],
