"adm.al_a_gov_user_renewed": ["Kept an official's access (yearly review)", "अधिकारी की पहुँच रखी (वार्षिक समीक्षा)"],
"adm.al_a_gov_user_removed": ["Removed an official's government access", "अधिकारी की सरकारी पहुँच हटाई"],
"rep.gs_t": ["Share with the state government", "राज्य सरकार के साथ साझा करें"],
"rep.gs_intro": ["If your state uses GrievIQ's government dashboard, complaints in your area appear there only inside the totals for the whole district: never your office's name or its own figures. You can choose to show your office's figures too. No citizen's name, phone number or complaint text is ever shown.", "यदि आपका राज्य GrievIQ का सरकारी डैशबोर्ड इस्तेमाल करता है, तो आपके क्षेत्र की शिकायतें वहाँ केवल पूरे ज़िले के कुल योग में दिखती हैं: कभी आपके कार्यालय का नाम या उसके अपने आँकड़े नहीं। आप अपने कार्यालय के आँकड़े भी दिखाना चुन सकते हैं। किसी नागरिक का नाम, फ़ोन नंबर या शिकायत का पाठ कभी नहीं दिखाया जाता।"],
"rep.gs_off": ["Not shared. The state sees only district totals.", "साझा नहीं। राज्य केवल ज़िले का कुल योग देखता है।"],
"rep.gs_on": ["Shared since {date} (chosen by {by}). The state sees your office's own figures, marked \"shared by the office\".", "{date} से साझा ({by} ने चुना)। राज्य आपके कार्यालय के अपने आँकड़े देखता है, \"कार्यालय द्वारा साझा\" चिह्न के साथ।"],
"rep.gs_start": ["Share my office's figures", "मेरे कार्यालय के आँकड़े साझा करें"],
"rep.gs_confirm": ["The state government will see your office's figures: complaints received, resolved and pending, time taken and citizens' ratings. You can stop at any time.", "राज्य सरकार आपके कार्यालय के आँकड़े देखेगी: प्राप्त, हल और लंबित शिकायतें, लगा समय और नागरिकों की रेटिंग। आप कभी भी रोक सकते हैं।"],
"rep.gs_yes": ["Yes, share", "हाँ, साझा करें"],
"rep.gs_stop": ["Stop sharing", "साझा करना बंद करें"],
"rep.gs_rep_only": ["Only the representative can change this.", "इसे केवल जनप्रतिनिधि बदल सकते हैं।"],
"rep.gs_saved_on": ["Your office's figures are now shared with the state government.", "आपके कार्यालय के आँकड़े अब राज्य सरकार के साथ साझा हैं।"],
"rep.gs_saved_off": ["Sharing stopped. The state sees only district totals.", "साझा करना बंद। राज्य केवल ज़िले का कुल योग देखता है।"],
"rep.gs_err": ["Couldn't save. Please try again.", "सहेजा नहीं जा सका। कृपया फिर से कोशिश करें।"],
"rep.act_gov_on": ["started sharing the office's figures with the state government", "कार्यालय के आँकड़े राज्य सरकार के साथ साझा करना शुरू किया"],
"rep.act_gov_off": ["stopped sharing the office's figures with the state government", "कार्यालय के आँकड़े राज्य सरकार के साथ साझा करना बंद किया"],
"adm.find_label": ["Type to find in the list", "सूची में खोजने के लिए लिखें"],
