"gv.signin_lede": ["For officials of a Union ministry, a state or a district named in their government's letter to GrievIQ. We'll email you a 6-digit code.", "किसी केंद्रीय मंत्रालय, राज्य या ज़िले के उन अधिकारियों के लिए जिनका नाम उनकी सरकार के GrievIQ को भेजे पत्र में है। हम आपको 6 अंकों का कोड ईमेल करेंगे।"],
"gv.email": ["Your email", "आपका ईमेल"],
"gv.email_hint": ["The address in your government's letter, usually name@nic.in or name@up.gov.in.", "आपकी सरकार के पत्र में दिया पता, आम तौर पर name@nic.in या name@up.gov.in।"],
"gv.signin_note": ["If your email isn't on record, no code will arrive. Ask your department to write to GrievIQ. GrievIQ never asks for your code by phone.", "यदि आपका ईमेल रिकॉर्ड में नहीं है, तो कोई कोड नहीं आएगा। अपने विभाग से GrievIQ को लिखने के लिए कहें। GrievIQ कभी फ़ोन पर आपका कोड नहीं माँगता।"],
