"gv.depts_p": ["Department offices that complaints were forwarded to, best first by work done on time. Choose an office for its details.", "वे विभागीय कार्यालय जिन्हें शिकायतें भेजी गईं, समय पर काम के अनुसार सबसे अच्छे पहले। विवरण के लिए कार्यालय चुनें।"],
"gv.depts_cap": ["Forwarded in {m}; \"with them now\" and \"late now\" are as of today.", "{m} में भेजे गए; \"अभी उनके पास\" और \"अभी देर\" आज की स्थिति है।"],
"gv.no_depts": ["No complaints were forwarded to a department here yet.", "यहाँ अभी किसी विभाग को कोई शिकायत नहीं भेजी गई।"],
