"gv.dept_sum": ["In {m}: {f} complaints forwarded to this office. {w} are with it now, {l} of them late.", "{m} में: इस कार्यालय को {f} शिकायतें भेजी गईं। {w} अभी इसके पास हैं, जिनमें से {l} में देर है।"],
