"gv.rp_pdf_hint": ["\"Save as PDF\" opens your browser's print window: choose \"Save as PDF\" as the printer. Hindi prints correctly this way.", "\"PDF के रूप में सहेजें\" आपके ब्राउज़र की प्रिंट विंडो खोलता है: प्रिंटर में \"Save as PDF\" चुनें। इस तरह हिन्दी सही छपती है।"],
