"gv.rp_foot": ["GrievIQ · No citizen's name, phone number, email or complaint text is included. Counts from 1 to 9 show as \"fewer than 10\".", "GrievIQ · किसी नागरिक का नाम, फ़ोन नंबर, ईमेल या शिकायत का पाठ शामिल नहीं है। 1 से 9 तक की गिनती \"10 से कम\" दिखती है।"],
