"gv.rp_followups": ["Follow-up requests", "अनुवर्ती अनुरोध"],
"gv.rp_followups_d": ["Requests between officials open during the month: the figure when asked and on the reply-by date, and whether the reply came in time.", "महीने में खुले रहे अधिकारियों के बीच के अनुरोध: पूछते समय और उत्तर-तिथि पर आँकड़ा, और क्या उत्तर समय पर आया।"],
"gv.rp_followups_note": ["Every request that was open at some time in the month and has this place at either end. The words of requests and replies are not in this report; they are on the dashboard.", "महीने में किसी भी समय खुला रहा हर अनुरोध, जिसके किसी भी छोर पर यह स्थान है। अनुरोधों और उत्तरों के शब्द इस रिपोर्ट में नहीं हैं; वे डैशबोर्ड पर हैं।"],
"gv.rp_col_fu_ref": ["Request", "अनुरोध"],
"gv.rp_col_fu_status": ["Status", "स्थिति"],
"gv.rp_col_fu_in_time": ["Replied in time", "समय पर उत्तर"],
"gv.rp_fu_yes": ["Yes", "हाँ"],
"gv.rp_fu_late": ["Late", "देर से"],
"gv.rp_fu_none": ["No reply by the date", "तिथि तक उत्तर नहीं"],
"gv.rp_fu_waiting": ["Not due yet", "अभी देय नहीं"],
"gv.ab_fu_t": ["Follow-up requests", "अनुवर्ती अनुरोध"],
"gv.ab_fu": ["A question from one office to another about one figure, with a reply-by date of 7, 15 or 30 days. GrievIQ records the figure when asked and measures it again on the reply-by date. It is not an official order: orders go by NIC email or eOffice, and their number is written in the request.", "किसी एक आँकड़े के बारे में एक कार्यालय से दूसरे कार्यालय को प्रश्न, 7, 15 या 30 दिन की उत्तर-तिथि के साथ। GrievIQ पूछते समय आँकड़ा दर्ज करता है और उत्तर-तिथि पर उसे फिर से मापता है। यह आधिकारिक आदेश नहीं है: आदेश NIC ईमेल या ई-ऑफ़िस से जाते हैं, और अनुरोध में उनकी संख्या लिखी जाती है।"],
"gv.rp_reps": ["Representatives' offices: totals by area", "जनप्रतिनिधियों के कार्यालय: क्षेत्रवार योग"],
"gv.rp_summary_d": ["The key figures, with last month and the same month last year beside them.", "मुख्य आँकड़े, पिछले माह और पिछले वर्ष के इसी माह के साथ।"],
"gv.rp_districts_d": ["Received, resolved, pending and more for each district (in a district: each city and block).", "हर ज़िले के लिए प्राप्त, निस्तारित, लंबित आदि (ज़िले में: हर शहर और ब्लॉक)।"],
"gv.rp_departments_d": ["Each government department office, best first by work done on time.", "हर सरकारी विभाग कार्यालय, समय पर काम के अनुसार सबसे अच्छे पहले।"],
"gv.rp_pending30_d": ["How many cases each department office has had for more than 30 days. Counts only, no case details.", "हर विभागीय कार्यालय के पास 30 दिन से अधिक समय से कितने मामले हैं। केवल गिनती, मामलों का विवरण नहीं।"],
"gv.rp_themes_d": ["Complaints received by ISO 37120 theme, month by month.", "ISO 37120 विषय के अनुसार प्राप्त शिकायतें, माहवार।"],
"gv.rp_reps_d": ["Totals for the elected representatives' offices in each area, with no office named.", "हर क्षेत्र में निर्वाचित जनप्रतिनिधियों के कार्यालयों का योग, किसी कार्यालय के नाम के बिना।"],
"gv.rp_summary_note": ["\"Same month last year\" is empty or low until GrievIQ has been in use for a year.", "GrievIQ के एक वर्ष उपयोग होने तक \"पिछले वर्ष का यही माह\" खाली या कम रहेगा।"],
"gv.rp_pending30_note": ["Counted from the day the citizen filed the complaint. The last row is cases still with representatives' offices, not yet forwarded to a department; no office is named.", "नागरिक के शिकायत दर्ज करने के दिन से गिना गया। अंतिम पंक्ति वे मामले हैं जो अभी जनप्रतिनिधियों के कार्यालयों के पास हैं, किसी विभाग को नहीं भेजे गए; किसी कार्यालय का नाम नहीं है।"],
"gv.rp_themes_note": ["Each month counts complaints filed in that month.", "हर माह में उसी माह दर्ज शिकायतें गिनी गई हैं।"],
"gv.rp_reps_note": ["Representatives of every party use GrievIQ. Their offices are never named or ranked here; \"offices\" counts the wards and villages whose representative uses GrievIQ.", "हर दल के जनप्रतिनिधि GrievIQ का उपयोग करते हैं। यहाँ उनके कार्यालयों का कभी नाम या रैंक नहीं दिया जाता; \"कार्यालय\" उन वार्डों और गाँवों की गिनती है जिनके जनप्रतिनिधि GrievIQ का उपयोग करते हैं।"],
