"adm.gv_national_h": ["Only on a letter from a Union ministry or department naming this official. They will see every state side by side, with the same rules: representatives' offices only as totals, and no citizen details.", "केवल किसी केंद्रीय मंत्रालय या विभाग के पत्र पर, जिसमें इस अधिकारी का नाम हो। वे हर राज्य को साथ-साथ देखेंगे, उन्हीं नियमों के साथ: जनप्रतिनिधियों के कार्यालय केवल योग के रूप में, और नागरिकों का कोई विवरण नहीं।"],
