"gv.signin_lede_state": ["For state and district officials named in their government's letter to GrievIQ. We'll email you a 6-digit code.", "उन राज्य और ज़िला अधिकारियों के लिए जिनका नाम उनकी सरकार के GrievIQ को भेजे पत्र में है। हम आपको 6 अंकों का कोड ईमेल करेंगे।"],
"gv.signin_lede_national": ["For officials of a Union ministry or department named in its letter to GrievIQ. We'll email you a 6-digit code.", "किसी केंद्रीय मंत्रालय या विभाग के उन अधिकारियों के लिए जिनका नाम उसके GrievIQ को भेजे पत्र में है। हम आपको 6 अंकों का कोड ईमेल करेंगे।"],
"gv.door_to_state": ["A state or district official?", "राज्य या ज़िला अधिकारी हैं?"],
"gv.door_to_national": ["An official of a Union ministry?", "किसी केंद्रीय मंत्रालय के अधिकारी हैं?"],
"gv.door_h": ["GrievIQ for governments", "सरकारों के लिए GrievIQ"],
"gv.door_p": ["Choose your dashboard. Both show the same figures, kept to the same rules: no citizen details, and elected representatives' offices only as totals.", "अपना डैशबोर्ड चुनें। दोनों एक ही आँकड़े, एक ही नियमों के साथ दिखाते हैं: नागरिकों का कोई विवरण नहीं, और निर्वाचित जनप्रतिनिधियों के कार्यालय केवल योग के रूप में।"],
"gv.door_state": ["State Dashboard", "राज्य डैशबोर्ड"],
"gv.door_state_p": ["For a state government and its districts: every district, department and ward, and the seven MIS reports.", "राज्य सरकार और उसके ज़िलों के लिए: हर ज़िला, विभाग और वार्ड, और सात MIS रिपोर्ट।"],
"gv.door_national": ["National Dashboard", "राष्ट्रीय डैशबोर्ड"],
"gv.door_national_p": ["For a Union ministry: every state side by side, down to districts and departments, and the same reports for the whole country.", "केंद्रीय मंत्रालय के लिए: हर राज्य साथ-साथ, ज़िलों और विभागों तक, और पूरे देश के लिए वही रिपोर्ट।"],
"gv.door_signin": ["Sign in", "साइन इन करें"],
"gv.door_demo": ["See the demo", "डेमो देखें"],
"gv.moved_state": ["You have state or district access, so you are on the State Dashboard.", "आपके पास राज्य या ज़िला पहुँच है, इसलिए आप राज्य डैशबोर्ड पर हैं।"],
"gv.moved_national": ["You have national access, so you are on the National Dashboard.", "आपके पास राष्ट्रीय पहुँच है, इसलिए आप राष्ट्रीय डैशबोर्ड पर हैं।"],
