"adm.gv_demo": ["demo", "डेमो"],
"adm.nav_handovers": ["Change of representative", "जनप्रतिनिधि परिवर्तन"],
"adm.ho_page_title": ["GrievIQ Admin — Change of representative", "GrievIQ एडमिन — जनप्रतिनिधि परिवर्तन"],
"adm.ho_sub": ["When a ward's, village's, mayor's, MLA's or MP's seat passes to someone else, record it here: a new representative, an administrator, or a vacant seat.", "जब किसी वार्ड, गाँव, महापौर, विधायक या सांसद का पद किसी और को मिले, यहाँ दर्ज करें: नया जनप्रतिनिधि, प्रशासक, या रिक्त पद।"],
"adm.ho_note": ["<b>The rules:</b> record a change only on official evidence (the election result, the government order, or the resignation accepted), with its number or link. A data entry operator asks; a super or operations admin approves, never their own request, or applies it directly. The office's complaints and records stay with the office.", "<b>नियम:</b> परिवर्तन केवल आधिकारिक प्रमाण (चुनाव परिणाम, सरकारी आदेश, या स्वीकृत त्यागपत्र) पर, उसकी संख्या या लिंक के साथ दर्ज करें। डेटा एंट्री ऑपरेटर अनुरोध करता है; सुपर या संचालन एडमिन स्वीकृत करता है (अपना अनुरोध कभी नहीं) या सीधे लागू करता है। कार्यालय की शिकायतें और रिकॉर्ड कार्यालय के पास रहते हैं।"],
"adm.ho_not_ready": ["This needs the part36 database update first.", "इसके लिए पहले part36 डेटाबेस अपडेट चाहिए।"],
