"adm.ho_st_ADMINISTRATOR": ["Administrator", "प्रशासक"],
"adm.ho_st_VACANT": ["Vacant: complaints go straight to the next level", "रिक्त: शिकायतें सीधे अगले स्तर पर जाती हैं"],
"adm.ho_f_kind": ["What is changing", "क्या बदल रहा है"],
"adm.ho_k_NEW_REP": ["A new representative", "नया जनप्रतिनिधि"],
"adm.ho_k_ADMINISTRATOR": ["An administrator takes charge", "प्रशासक कार्यभार लेता है"],
"adm.ho_k_VACANT": ["The seat becomes vacant", "पद रिक्त होता है"],
"adm.ho_vacant_h": ["While the seat is vacant, citizens can still file complaints; they go straight to the next level, which is not marked late for the empty seat.", "पद रिक्त रहने पर भी नागरिक शिकायत दर्ज कर सकते हैं; वे सीधे अगले स्तर पर जाती हैं, और रिक्त पद के कारण उस स्तर को देर नहीं मानी जाती।"],
"adm.ho_f_newName": ["New representative's name", "नए जनप्रतिनिधि का नाम"],
