"adm.ho_what_h": ["When this is applied:", "लागू होने पर:"],
"adm.ho_what_1": ["the seat shows the new person (or vacant) at once, to citizens and in the escalation chain;", "पद पर नया व्यक्ति (या रिक्त) तुरंत दिखता है, नागरिकों को और शिकायत श्रृंखला में;"],
"adm.ho_what_2": ["the outgoing person's sign-ins and phone alerts end, unless they hold another office;", "जाने वाले व्यक्ति के साइन-इन और फ़ोन सूचनाएँ बंद होती हैं, जब तक उनके पास कोई और कार्यालय न हो;"],
"adm.ho_what_3": ["the office's team is paused until the new person confirms them, and cases assigned to the old team return to the office's open list;", "कार्यालय की टीम तब तक रुकी रहती है जब तक नया व्यक्ति पुष्टि न करे, और पुरानी टीम को सौंपे मामले कार्यालय की खुली सूची में लौटते हैं;"],
"adm.ho_what_4": ["sharing the office's figures with the state is switched off until the new person chooses it;", "राज्य के साथ कार्यालय के आँकड़े साझा करना तब तक बंद रहता है जब तक नया व्यक्ति न चुने;"],
"adm.ho_what_5": ["both people get a short email with no complaint details, and the new person sees a handover summary.", "दोनों को बिना शिकायत विवरण का छोटा ईमेल जाता है, और नए व्यक्ति को हस्तांतरण सारांश दिखता है।"],
