"rep.ho_team_p": ["The previous team is paused: they can't see or change anything until you confirm each person you want to keep, in Team. Remove anyone who has left.", "पिछली टीम रुकी हुई है: जब तक आप टीम में हर रखे जाने वाले व्यक्ति की पुष्टि न करें, वे कुछ देख या बदल नहीं सकते। जो चले गए हैं उन्हें हटाएँ।"],
