"ntc.pause_now": ["An election code is in force for {office}: {list}. Its notices are paused and new ones can't start until it ends.", "{office} के लिए चुनाव आचार संहिता लागू है: {list}। इसकी सूचनाएँ रुकी हैं और इसके समाप्त होने तक नई शुरू नहीं हो सकतीं।"],
"ntc.pause_next": ["An election code is coming for {office}: {list}. Notices are paused during it and the days are added back.", "{office} के लिए चुनाव आचार संहिता आने वाली है: {list}। इसके दौरान सूचनाएँ रुकेंगी और वे दिन बाद में जोड़े जाएँगे।"],
