"ntc.e_EMOJI": ["Emoji aren't allowed. Use plain words.", "इमोजी की अनुमति नहीं है। सादे शब्दों का प्रयोग करें।"],
"ntc.e_CAPS": ["Please don't write it all in capital letters.", "कृपया पूरा पाठ बड़े अक्षरों में न लिखें।"],
"ntc.e_DATE": ["Choose a real date.", "सही तारीख़ चुनें।"],
