"ntc.e_PAUSED": ["An election code is in force on that date. Choose a date after it ends.", "उस तारीख़ को चुनाव आचार संहिता लागू है। इसके समाप्त होने के बाद की तारीख़ चुनें।"],
"ntc.e_LIMIT": ["Your office already has {n} notices waiting or running, the most allowed at once. Ask again when one ends.", "आपके कार्यालय की पहले से {n} सूचनाएँ प्रतीक्षा में या चल रही हैं, जो एक साथ अधिकतम सीमा है। किसी एक के समाप्त होने पर फिर अनुरोध करें।"],
"ntc.e_VACANT": ["This seat is vacant, so it can't ask for notices.", "यह पद रिक्त है, इसलिए सूचना का अनुरोध नहीं किया जा सकता।"],
"ntc.e_PAYMENT_REPORTED": ["A payment for this bill is being checked, so it can't be taken back now. Please contact GrievIQ support.", "इस बिल के भुगतान की जाँच हो रही है, इसलिए अभी वापस नहीं लिया जा सकता। कृपया GrievIQ सहायता से संपर्क करें।"],
"ntc.e_generic": ["Something went wrong. Please try again.", "कुछ गड़बड़ हुई। कृपया फिर प्रयास करें।"],
