"ntc.e_load": ["Your notices couldn't be loaded. Please reload the page.", "आपकी सूचनाएँ लोड नहीं हो सकीं। कृपया पृष्ठ फिर लोड करें।"],
"ntc.cat_ex_CAMP": ["e.g. ration card or pension help desk", "जैसे राशन कार्ड या पेंशन सहायता डेस्क"],
"ntc.cat_ex_SCHEME": ["e.g. Ayushman card enrolment", "जैसे आयुष्मान कार्ड पंजीकरण"],
