"ntc.cat_ex_OFFICE": ["e.g. new hours or a new phone number", "जैसे नया समय या नया फ़ोन नंबर"],
"ntc.cat_ex_SERVICE": ["e.g. water supply off on Sunday", "जैसे रविवार को जलापूर्ति बंद"],
