"rep.tab_notices": ["Notices", "सूचनाएँ"],
"dd.ntc_h": ["Public notices", "सार्वजनिक सूचनाएँ"],
"dd.ntc_p": ["Tell people in your area about a service interruption, a camp or safety advice, on their ward or village page in GrievIQ. Paid, checked by GrievIQ first.", "अपने क्षेत्र के लोगों को GrievIQ में उनके वार्ड या गाँव के पृष्ठ पर सेवा में रुकावट, शिविर या सुरक्षा सलाह के बारे में बताएँ। सशुल्क, पहले GrievIQ द्वारा जाँची गई।"],
"dd.ntc_open": ["Open public notices", "सार्वजनिक सूचनाएँ खोलें"],
"bill.notice_period": ["As shown under Notices (it starts when this bill is paid)", "जैसा सूचनाएँ में दिखाया गया है (यह बिल भुगतान होने पर शुरू होती है)"],
"adm.bl_notice_link": ["see Public notices", "सार्वजनिक सूचनाएँ देखें"],
"adm.nav_notices": ["Public notices", "सार्वजनिक सूचनाएँ"],
"adm.nt_page_title": ["GrievIQ Admin — Public notices", "GrievIQ एडमिन — सार्वजनिक सूचनाएँ"],
"adm.nt_sub": ["Paid notices that offices ask to show on the ward and village pages of their area. Check each one, approve or turn it back, and pause them during an election code.", "सशुल्क सूचनाएँ जिन्हें कार्यालय अपने क्षेत्र के वार्ड और गाँव पृष्ठों पर दिखाना चाहते हैं। हर एक को जाँचें, स्वीकृत करें या लौटाएँ, और चुनाव आचार संहिता के दौरान रोकें।"],
"adm.nt_note": ["<b>The rules:</b> public information only (camps, help desks, schemes, health camps, ward or gram sabha meetings, office timings, service interruptions, safety advice). Never a party name, symbol, slogan or appeal for votes, never praise of a person or of achievements, nothing about any citizen or complaint, no photos or links. A department's notice, and any notice about a scheme, a health camp or a service interruption, needs the authority letter: open it and verify it before approving. Every notice is labelled \"Paid notice\" with who paid for it. Every office pays the same price; nobody can pay to be shown first.", "<b>नियम:</b> केवल सार्वजनिक जानकारी (शिविर, सहायता डेस्क, योजनाएँ, स्वास्थ्य शिविर, वार्ड या ग्राम सभा बैठकें, कार्यालय समय, सेवा में रुकावट, सुरक्षा सलाह)। कभी कोई दल का नाम, चिह्न, नारा या वोट की अपील नहीं, किसी व्यक्ति या उपलब्धियों की प्रशंसा नहीं, किसी नागरिक या शिकायत के बारे में कुछ नहीं, कोई फ़ोटो या लिंक नहीं। विभाग की सूचना, और योजना, स्वास्थ्य शिविर या सेवा में रुकावट की किसी भी सूचना के लिए प्राधिकार पत्र आवश्यक है: स्वीकृति से पहले इसे खोलकर सत्यापित करें। हर सूचना पर \"सशुल्क सूचना\" और भुगतानकर्ता का नाम होता है। हर कार्यालय समान मूल्य देता है; कोई भी पहले दिखने के लिए भुगतान नहीं कर सकता।"],
"adm.nt_prices_link": ["Change notice plans and prices in Prices & site details → Public notices", "सूचना योजनाएँ और मूल्य मूल्य एवं साइट विवरण → सार्वजनिक सूचनाएँ में बदलें"],
"adm.nt_not_ready": ["Public notices aren't set up yet. Run the database update part38-notices.sql.", "सार्वजनिक सूचनाएँ अभी शुरू नहीं हुई हैं। डेटाबेस अपडेट part38-notices.sql चलाएँ।"],
"adm.nt_off": ["Offices can't ask for new notices: switched off in Prices & site details.", "कार्यालय नई सूचनाओं का अनुरोध नहीं कर सकते: मूल्य एवं साइट विवरण में बंद है।"],
"adm.nt_wait_h": ["Waiting for approval ({n})", "स्वीकृति की प्रतीक्षा ({n})"],
"adm.nt_wait_none": ["Nothing is waiting.", "कुछ भी प्रतीक्षा में नहीं है।"],
"adm.nt_run_h": ["Approved, scheduled and showing ({n})", "स्वीकृत, निर्धारित और दिख रही ({n})"],
"adm.nt_run_p": ["Approved notices start once their bill is paid. A paid notice can be taken down at once if it breaks the rules.", "स्वीकृत सूचनाएँ बिल भुगतान के बाद शुरू होती हैं। नियम तोड़ने पर भुगतान की गई सूचना तुरंत हटाई जा सकती है।"],
"adm.nt_run_none": ["None at the moment.", "अभी कोई नहीं।"],
"adm.nt_record_h": ["Record", "रिकॉर्ड"],
"adm.nt_record_p": ["Ended, not approved, taken back, taken down or cancelled. Every step is also in the audit log.", "समाप्त, अस्वीकृत, वापस ली गई, हटाई गई या रद्द। हर कदम ऑडिट लॉग में भी है।"],
