"adm.nt_c_PUBLIC_INFO": ["It is public information of the kind chosen, useful to people in this area.", "यह चुने गए प्रकार की सार्वजनिक जानकारी है, जो इस क्षेत्र के लोगों के लिए उपयोगी है।"],
"adm.nt_c_NO_PARTY": ["No party name, symbol, slogan, candidate or request for votes, in either language.", "किसी भी भाषा में कोई दल का नाम, चिह्न, नारा, प्रत्याशी या वोट की अपील नहीं।"],
"adm.nt_c_NO_PRAISE": ["No praise of a person, and no claims of achievements or thanks to anyone.", "किसी व्यक्ति की प्रशंसा नहीं, और किसी उपलब्धि का दावा या किसी को धन्यवाद नहीं।"],
"adm.nt_c_NO_CITIZEN": ["Nothing about any citizen or complaint.", "किसी नागरिक या शिकायत के बारे में कुछ नहीं।"],
"adm.nt_c_TRUTHFUL": ["Clear, truthful and not misleading; dates and place make sense.", "स्पष्ट, सत्य और भ्रामक नहीं; तारीख़ और स्थान उचित हैं।"],
