"adm.nt_reject_note": ["Reason for turning it back", "लौटाने का कारण"],
"adm.nt_reject_h": ["The office sees this and can ask again. For example: \"Remove the line thanking the MLA.\"", "कार्यालय इसे देखेगा और फिर अनुरोध कर सकता है। उदाहरण: \"विधायक को धन्यवाद वाली पंक्ति हटाएँ।\""],
