"adm.nt_takedown_note": ["Reason", "कारण"],
"adm.nt_takedown_hint": ["At least 10 characters. The office is emailed the reason.", "कम से कम 10 अक्षर। कार्यालय को कारण ईमेल किया जाएगा।"],
"adm.nt_takedown": ["Take down now", "अभी हटाएँ"],
"adm.nt_takedown_q": ["Take {ref} down now? It stops showing at once.", "{ref} अभी हटाएँ? यह तुरंत दिखना बंद हो जाएगी।"],
"adm.nt_e_reason_short": ["Write a reason (at least 5 characters).", "कारण लिखें (कम से कम 5 अक्षर)।"],
