    addDepts: function (names) { if (names) Object.keys(names).forEach(function (k) { var n = names[k]; if (n && n.en) DEPT_NAMES[k] = [n.en, n.hi || n.en]; }); },
    dept: function (name) { if (DEPT_NAMES[name]) return pick(DEPT_NAMES[name]); return DEPTS[name] ? t(DEPTS[name]) : (name || ''); },
    // Oct 2026: the checks on a citizen's complaint photo, for staff pages.
