        C_NO_CAMERA: ['ev.c_no_camera', 'warn'], C_OLD_PHOTO: ['ev.c_old', 'warn'], C_DUP: [w.kind === 'similar' ? 'ev.c_similar' : 'ev.c_dup', 'warn'],
